window.DICTIONARY_ENTRY_SHARDS["0070-0079"]={"0070-0079:9d29571ca2c3b5":{"word":"pyrogen","partOfSpeech":"Adjektiv","gender":"","hyphenation":{"de-CH":"py·ro·gen","de-DE":"py·ro·gen"},"forms":[{"form":"pyrogen","tags":["Positiv"]},{"form":"pyrogene","tags":["Positiv","Nominativ","strong","Singular","feminine"]},{"form":"pyrogenem","tags":["Positiv","Dativ","strong","Singular","masculine"]},{"form":"pyrogenen","tags":["Positiv","Genitiv","strong","Singular","masculine"]},{"form":"pyrogener","tags":["Positiv","Nominativ","strong","Singular","masculine"]},{"form":"pyrogenes","tags":["Positiv","Nominativ","strong","Singular","neuter"]},{"form":"er ist pyrogen","tags":["Positiv","predicative","Singular","masculine"]},{"form":"es ist pyrogen","tags":["Positiv","predicative","Singular","neuter"]},{"form":"sie ist pyrogen","tags":["Positiv","predicative","Singular","feminine"]},{"form":"sie sind pyrogen","tags":["Positiv","predicative","Plural"]}],"senses":[{"definition":"eine Erhöhung der Körpertemperatur hervorrufend"},{"definition":"aus feurigem Magma entstanden"}],"synonyms":["fiebererzeugend","pyretisch"],"origins":["Neologismus, zusammengesetzt aus dem Wortbildungselement pyro- in der Bedeutung „Feuer, Hitze“ und „das Fieber betreffend“, von altgriechisch πῦρ (pyr^☆) ^(→ grc), Genitiv πῦρός (pyros^☆) ^(→ grc) „Feuer“, und dem Suffix -gen"],"examples":[{"text":"„Schüttelfrost und Fieber sind auf eine Verstellung des Sollwertes zurückzuführen. Diese Veränderung kann durch Krankheitserreger durch die Ausschüttung pyrogener (Fieber erzeugender) Stoffe verursacht werden oder durch den Körper selbst, um die Reaktionen der Immunantwort zu beschleunigen.“","reference":"Wikipedia-Artikel „System“ (Stabilversion)"},{"text":"Daneben können verschiedene exogen zugeführte Stoffe (Blutderivate, Medikamente, Drogen, Gifte) akut pyrogen wirken.","reference":"Journal suisse de médicine. 13. Auflage. Band 123, B. Schwabe, 1993, Seite 819 (zitiert nach Google Books) ."},{"text":"Wenn auch solche Flächen an pyrogenen Quarzen bisher wohl niemals beobachtet sind, steht doch nichts im Wege anzunehmen, daß sie dort und namentlich auch an Bergkristallen oberhalb 575° gebildet werden könnten.","reference":"Zentralblatt für Mineralogie, Geologie und Paläontologie in Verbindung mit dem Neuen Jahrbuch für Mineralogie, Geologie, und Paläontologie. 1921 (zitiert nach Google Books) ."},{"text":"Alle pyrogenen wie neptunischen Gesteins-Bildungen, einige quartäre ausgenommen, befanden sich ursprünglich auf oder nahe an der niedrigsten Oxydations-Stufe, nie auf dem Maximum.","reference":"K.C. Leonhard, H.G. Bronn: Neues Jahrbuch fur Mineralogie, Geognosie, Geologie und Petrefaktenkunde. E. Schweizerbart'sche Verlagshandlung und Druckerei, Stuttgart 1855, Seite PA725 (zitiert nach Google Books) ."},{"text":"Eine besondere Form von Füllstoffen stellen pyrogene Kieselsäuren dar. … Pyrogene Kieselsäure wird synthetisch durch Flammenhydrolyse hergestellt.","reference":"Detlef Gysau: Füllstoffe: Grundlagen und Anwendungen. Vincentz Network GmbH & Co KG, 2006, ISBN 9783878703372, Seite 129 (zitiert nach Google Books) ."}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation","openthesaurus"],"sourceWord":"pyrogen","id":"9d29571ca2c3b5"},"0070-0079:6bcb32ab868d98":{"word":"Pyramide","partOfSpeech":"Substantiv","gender":"die","hyphenation":{"de-CH":"Py·ra·mi·de","de-DE":"Py·ra·mi·de"},"forms":[{"form":"Pyramide","tags":["Nominativ","Singular"]},{"form":"Pyramiden","tags":["Nominativ","Plural"]}],"senses":[{"definition":"geometrischer Körper, der von einem Vieleck als Grundfläche und von sich in einer Spitze treffenden Dreiecken begrenzt wird"},{"definition":"Grab- oder Tempelbau in Form einer Pyramide^([1]) mit rechteckiger Grundfläche"},{"definition":"Gebilde in Form einer Pyramide^([1])"},{"definition":"sich drehendes Lichtergestell als Weihnachtsdekoration aus dem Erzgebirge"}],"synonyms":[],"origins":["Gegen Ende des 15. Jahrhunderts von lateinisch pyramis ^(→ la) entlehnt, das von griechisch πυραμίς (pyramis^☆) ^(→ grc) übernommen wurde und letztlich aus dem Ägyptischen stammt; verwandt mit pyr- (im Sinne von heben und empor) sowie auch Pyrenäen"],"examples":[{"text":"„Die allgemeinen Eigenschaften der Pyramide sind aus der Stereometrie bekannt. Sie ist ein Polyeder, welches über einem Vieleck als Grundfläche (Basis) von lauter Dreiecken als Seitenflächen (Pleura) dergestalt umschlossen wird, dass dieselben in einem einzigen Punkt, der Spitze (Apex), zusammenlaufen.“","reference":"Ernst Haeckel: Generelle Morphologie der Organismen. Allgemeine Grundzüge der organischen Formen-Wissenschaft, mechanisch begründet durch die von Charles Darwin reformirte Descendenz-Theorie. Erster Band: Allgemeine Anatomie der Organismen. Berlin, 1866, S.454"},{"text":"Ägyptische Pyramiden sind größer als die Pyramiden der Maya.","reference":""},{"text":"„Immer schon haben die Maya ihre Pyramiden und den Fassadenschmuck ihrer Tempel bemalt.“","reference":"Berthold Riese: Die Maya. Geschichte, Kultur, Religion. 4. Auflage. Verlag C.H. Beck, München 1995, ISBN 978-3-406-39826-1, Seite 39."},{"text":"„Auf ihnen erhoben sich die drei Tempel, der alte und der neue Tempel sowie das Castillo, das urspünglich eine 15 Meter hohe Pyramide war.“","reference":"Dietrich Ecklebe: Peru: Kulturen vor den Inka (Teil 1). In: philatelie. Nummer Heft 543, 2022 , Seite 47-51, Zitat S. 49."},{"text":"„Leonardo beobachtete die Vögel bei ihrer Technik, mit weit ausgebreiteten Flügeln langsam abzusinken und entwarf einen Fallschirm in Form einer viereckigen Pyramide, […].“","reference":"Siegbert A. Warwitz: Sinnsuche im Wagnis. Leben in wachsenden Ringen. Erklärungsmodelle für grenzüberschreitendes Verhalten. Schneider, Baltmannsweiler 2016, ISBN 978-3-8340-1620-1 , Seite 83."},{"text":"„Lee Jay drehte den Baseball in der Handfläche herum und beugte sich vor, um die Pyramide gründlich ins Auge zu fassen, wobei er unter seinen Haaren hervorspähte.“","reference":"Marc Steadman: Schwarze Chronik. Ein Südstaaten-Dekameron. Fischer Taschenbuch Verlag, Frankfurt am Main 1980 (Originaltitel: MacAfee county, übersetzt von Elisabeth Schnack), ISBN 3-596-22489-6, Seite 238 (englische Originalausgabe 1970) ."},{"text":"Weihnachten ohne Pyramide ist im Erzgebirge gar nicht vorstellbar.","reference":""}],"idioms":[],"collocations":[],"derivations":["pyramidal","pyramidenartig","pyramidenförmig","Pyramidendach","Pyramidenenergie","Pyramidenstumpf","Pyramidion"],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Pyramide","id":"6bcb32ab868d98"},"0070-0079:1db2528954f9d5":{"word":"Pyxis","partOfSpeech":"Substantiv","gender":"die","hyphenation":{"de-CH":"Py·xis","de-DE":"Py·xis"},"forms":[{"form":"Pyxis","tags":["Nominativ","Singular"]},{"form":"Pyxiden","tags":["Nominativ","Plural"]}],"senses":[{"definition":"Büchse zur Aufbewahrung von Schmuckstücken"},{"definition":"verzierte Dose zur Aufbewahrung von konsekrierten Hostien"},{"definition":"Sternbild des Südhimmels"}],"synonyms":[],"origins":[],"examples":[{"text":"Die Pyxis der Archäologischen Sammlungen der Karl-Franzens-Universität Graz repräsentiert einen Typ, der sich durch seine zylindrische Form und einen flachen Deckel ohne Knauf auszeichnet.","reference":"Uni Graz, gelesen 05/2012"},{"text":"Vor dem 14. Jahrhundert wurde die Hostie oft in einem verhüllten Kelch oder auch in einer Pyxis verwahrt. Danach ging man dazu über, sie zum Beispiel in einer Monstranz sichtbar der Anbetung auszusetzen.","reference":""},{"text":"Argo ist in vier Sternbilder aufgeteilt: Carina, Puppis, Pyxis und Vela.","reference":""}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Pyxis","id":"1db2528954f9d5"},"0070-0079:2054309224c785":{"word":"Pyrrhussieg","partOfSpeech":"Substantiv","gender":"der","hyphenation":{"de-CH":"Pyr·rhus·sieg","de-DE":"Pyr·rhus·sieg"},"forms":[{"form":"Pyrrhussieg","tags":["Nominativ","Singular"]},{"form":"Phyrrus-Sieg","tags":["alternative"]},{"form":"Pyrrhussiege","tags":["Nominativ","Plural"]},{"form":"Pyrrhussiegs","tags":["Genitiv","Singular"]},{"form":"Pyrrhussiegen","tags":["Dativ","Plural"]},{"form":"Pyrrhussieges","tags":["Genitiv","Singular"]}],"senses":[{"definition":"ein unter (äußerst) hohem Einsatz und unter (zu großen) Opfern errungener Erfolg, der aufgrund dessen keinen Vorteil mehr darstellt und (mittelfristig) eher einem Fehlschlag/einer Niederlage gleichkommt"}],"synonyms":[],"origins":["strukturell:","Kompositum aus dem Eigennamen Pyrrhus und dem Substantiv Sieg","etymologisch:","Bei dem Wort handelt es sich um eine seit dem 20. Jahrhundert bezeugte Bezeichnung nach dem Namen des Königs Pyrrhus von Epirus, der einen sehr verlustreichen Sieg über die Römer in der Schlacht bei Asculum 280/279 vor unserer Zeitrechnung errang."],"examples":[{"text":"Dieser Erfolg könnte sich als Pyrrhussieg erweisen.","reference":""},{"text":"Dieser Wahlsieg war ein Pyrrhussieg für die SPD.","reference":""},{"text":"„Nach ihren ersten Pyrrhussiegen in den nun besetzten Gebieten fanden immer mehr Anhänger der Fedayeen im jordanischen al-Ġaur Zuflucht und unternahmen mit Unterstützung des radikalen Flügels der Muslimbruderschaft, dem sich vermutlich viele enttäuschte und geflüchtete Muslimbrüder aus der Westbank angeschlossen hatten, Angriffe auf israelisches Territorium.“","reference":"Denis Engelleder: Die islamistische Bewegung in Jordanien und Palästina 1945–1989. In: Jenaer Beiträge zum Vorderen Orient. 6. Band, Harrassowitz Verlag, Wiesbaden 2002, ISBN 978-3-447-04593-3, ISSN 0949-6815, Seite 135 (Zitiert nach Google Books) .\nIm Originalsatz ist einzig die Bezeichnung »al-Ġaur« kursiv gesetzt."},{"text":"„Heute wissen wir, dass der Sieg von 1967 ein Pyrrhussieg war.“","reference":"Amos Elon: Was ist falsch gelaufen? EIN RÜCKBLICK AUF DIE GESCHICHTE ISRAELS. In: Le Monde diplomatique Online. Deutschsprachige Ausgabe. Nummer 7028, 11. April 2003 (übersetzt von Niels Kadritzke), ISSN 1434-2561, Seite 12–13 (URL, abgerufen am 7. November 2012) ."},{"text":"„Auf die Vernichtung der Janitscharen folgte der Ruin ihrer jüdischen Partner, womit die Armenier freie Bahn hatten - im Endeffekt freilich ein Pyrrhussieg.“","reference":"Bernard Lewis: Die Juden in der islamischen Welt. 1. Auflage. C. H. Beck, München 2004 (Originaltitel: The Jews of Islam, übersetzt von Liselotte Julius), ISBN 978-3-406-51074-8, Seite 156 (Zitiert nach Google Books) ."},{"text":"„Bislang sind die meisten Umwelterfolge in China nur Pyrrhussiege.“","reference":"Georg Blume: Vom Skandal zum Erfolg. In: taz.de. 21. Februar 2005, ISSN 2626-5761 (URL, abgerufen am 7. November 2012) ."},{"text":"„Vier Jahrzehnte später findet man in den israelischen Medien kaum einen Jubiläumskommentar, der nicht von einem Pyrrhussieg spricht.“","reference":"Thorsten Schmitz: Der Sechs-Tage-Krieg: Der hohe Preis des schnellen Sieges. In: sueddeutsche.de. 4. Juni 2007, ISSN 0174-4917 (URL, abgerufen am 7. November 2012) ."},{"text":"„Sarkissjan hatte die Präsidentschaftswahlen vom 19. Februar mit 52,9 Prozent der Stimmen knapp für sich entschieden - doch danach büßte er so sehr an Glaubwürdigkeit ein, dass sein Wahlerfolg nachträglich zum Pyrrhussieg geriet.“","reference":"Jean Gueyras: Zwei Verbrecher und ein Hexer. Armenien hat einen neuen Präsidenten und eine neue Opposition. In: Le Monde diplomatique Online. Deutschsprachige Ausgabe. Nummer 8552, 11. April 2008 (übersetzt von Edgar Peinelt), ISSN 1434-2561 (URL, abgerufen am 7. November 2012) ."}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Pyrrhussieg","id":"2054309224c785"},"0070-0079:087f629a6164c3":{"word":"Pykniker","partOfSpeech":"Substantiv","gender":"der","hyphenation":{"de-CH":"Py·kni·ker","de-DE":"Py·kni·ker"},"forms":[{"form":"Pykniker","tags":["Nominativ","Singular"]},{"form":"Pyknikern","tags":["Dativ","Plural"]},{"form":"Pyknikers","tags":["Genitiv","Singular"]}],"senses":[{"definition":"Mann mit gesetztem Körperbau"}],"synonyms":[],"origins":[],"examples":[],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Pykniker","id":"087f629a6164c3"},"0070-0079:dccc344e897db6":{"word":"pyknisch","partOfSpeech":"Adjektiv","gender":"","hyphenation":{"de-CH":"py·knisch","de-DE":"py·knisch"},"forms":[{"form":"pyknisch","tags":["Positiv"]},{"form":"pyknische","tags":["Positiv","Nominativ","strong","Singular","feminine"]},{"form":"pyknischem","tags":["Positiv","Dativ","strong","Singular","masculine"]},{"form":"pyknischen","tags":["Positiv","Genitiv","strong","Singular","masculine"]},{"form":"pyknischer","tags":["Komparativ"]},{"form":"pyknisches","tags":["Positiv","Nominativ","strong","Singular","neuter"]},{"form":"pyknischere","tags":["Komparativ","Nominativ","strong","Singular","feminine"]},{"form":"pyknischste","tags":["Superlativ","Nominativ","strong","Singular","feminine"]},{"form":"pyknischerem","tags":["Komparativ","Dativ","strong","Singular","masculine"]},{"form":"pyknischeren","tags":["Komparativ","Genitiv","strong","Singular","masculine"]},{"form":"pyknischerer","tags":["Komparativ","Nominativ","strong","Singular","masculine"]},{"form":"pyknischeres","tags":["Komparativ","Nominativ","strong","Singular","neuter"]},{"form":"pyknischstem","tags":["Superlativ","Dativ","strong","Singular","masculine"]},{"form":"pyknischsten","tags":["Superlativ","Genitiv","strong","Singular","masculine"]},{"form":"pyknischster","tags":["Superlativ","Nominativ","strong","Singular","masculine"]},{"form":"pyknischstes","tags":["Superlativ","Nominativ","strong","Singular","neuter"]},{"form":"am pyknischsten","tags":["Superlativ"]},{"form":"er ist pyknisch","tags":["Positiv","predicative","Singular","masculine"]},{"form":"es ist pyknisch","tags":["Positiv","predicative","Singular","neuter"]},{"form":"sie ist pyknisch","tags":["Positiv","predicative","Singular","feminine"]},{"form":"er ist pyknischer","tags":["Komparativ","predicative","Singular","masculine"]},{"form":"es ist pyknischer","tags":["Komparativ","predicative","Singular","neuter"]},{"form":"sie sind pyknisch","tags":["Positiv","predicative","Plural"]},{"form":"sie ist pyknischer","tags":["Komparativ","predicative","Singular","feminine"]},{"form":"sie sind pyknischer","tags":["Komparativ","predicative","Plural"]},{"form":"er ist am pyknischsten","tags":["Superlativ","predicative","Singular","masculine"]},{"form":"es ist am pyknischsten","tags":["Superlativ","predicative","Singular","neuter"]},{"form":"sie ist am pyknischsten","tags":["Superlativ","predicative","Singular","feminine"]},{"form":"sie sind am pyknischsten","tags":["Superlativ","predicative","Plural"]}],"senses":[{"definition":"untersetzt, zu Fettansatz neigend"}],"synonyms":[],"origins":["Entlehnung aus dem Altgriechischen vom Adjektiv πυκνός (pyknos^☆) ^(→ grc) „dicht, fest, derb“"],"examples":[{"text":"Bei älteren und pyknisch veranlagten Menschen kann das Ok-Gewicht in den Bereich des leichten Übergewichts bis maximal BMI 30 reichen.","reference":"Eva Marbach: Erfolgreich abnehmen durch Hintergrundwissen. Zusammenhänge verstehen und Hindernisse gezielt ausräumen. BoD – Books on Demand, 2010, ISBN 9783938764244, Seite 43 (zitiert nach Google Books) ."}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"pyknisch","id":"dccc344e897db6"},"0070-0079:6560f75a48bb97":{"word":"Pyrenäen","partOfSpeech":"Toponym","gender":"","hyphenation":{"de-CH":"Py·re·nä·en","de-DE":"Py·re·nä·en"},"forms":[{"form":"Pyrenäen","tags":["Nominativ","Plural"]}],"senses":[{"definition":"das Grenzgebirge zwischen Frankreich und Spanien"}],"synonyms":[],"origins":[],"examples":[{"text":"„\"Pyrenäen\" - das war eine rostbraune Sache auf der sonst grünen und schwarzen Karte, darin ein paar Bergkleckse standen. … Dies waren die wissenschaftlichen Kenntnisse, die mir die deutsche Schule in Bezug auf die Pyrenäen mitgegeben hatte.“","reference":"Kurt Tucholsky: Ein Pyrenäenbuch, Reinbek bei Hamburg (Rowohlt), 1962, 35. Auflage 2004, Seite 9, ISBN 3 499 10474 1"},{"text":"„In den Pyrenäen war es kalt.“","reference":"Johannes Mario Simmel: Es muß nicht immer Kaviar sein. Mit auserlesenen Kochrezepten des Geheimagenten wider Willen. Nikol, Hamburg 2015, ISBN 978-3-86820-292-2, Seite 257. Erstveröffentlichung Zürich 1960."},{"text":"„Sowie er die Pyrenäen überschritten hat, folgt der Sieg dem Enkel Heinrichs IV. überall.“","reference":"Gustave Flaubert: Bouvard und Pécuchet. Roman. Diogenes, Zürich 1979 (übersetzt von Erich Marx), ISBN 3-257-20725-5 , Seite 148. Französisch 1881."}],"idioms":[],"collocations":[],"derivations":["pyrenäisch"],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Pyrenäen","id":"6560f75a48bb97"},"0070-0079:bda53b4a212850":{"word":"Pyrogallol-5-carbonsäure","partOfSpeech":"Substantiv","gender":"die","hyphenation":{"de-CH":"Py·ro·gal·lol-5-car·bon·säu·re","de-DE":"Py·ro·gal·lol-5-car·bon·säu·re"},"forms":[{"form":"Pyrogallol-5-carbonsäure","tags":["Nominativ","Singular"]}],"senses":[{"definition":"Synonym von Gallussäure"}],"synonyms":[],"origins":[],"examples":[],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Pyrogallol-5-carbonsäure","id":"bda53b4a212850"},"0070-0079:e902a6d0526229":{"word":"Pyjama","partOfSpeech":"Substantiv","gender":"der","hyphenation":{"de-CH":"Py·ja·ma","de-DE":"Py·ja·ma"},"forms":[{"form":"Pyjama","tags":["Nominativ","Singular"]},{"form":"Pyjamas","tags":["Nominativ","Plural"]}],"senses":[{"definition":"zumeist aus leichtem Stoff gefertigtes sowie aus zusammengehörender Hose und Jacke bestehendes Kleidungsstück, das zum Schlafen getragen wird"}],"synonyms":["Nachtanzug","Nachtgewand","Nachthemd","Nachtkleid","Nachtwäsche","Nachtzeug","Schlafanzug"],"origins":["seit dem 20. Jahrhundert bezeugt; Entlehnung über englisch pyjamas ^(→ en) (in pluralischer Form in Analogie zu breeches ^(→ en), trousers ^(→ en) und so weiter) aus dem Hindi पजामा (pājāmā) ^(→ hi), पायजामा (pāyjāmā) ^(→ hi) beziehungsweise aus dem Urdu پاجامه (DMG: pā-ǧāma) ^(→ ur), پأيجامه (DMG: paʾi-ǧāma) ^(→ ur), beide „lose um die Hüfte geknüpfte Hose“, eigentlich „Beinkleid“; sowohl die Hindi- als auch die Urdu-Formen entstammen dem persischen ﭘاجامه (DMG: pā-ǧāma) ^(→ fa) ‚Beinkleid‘","Die Europäer übernehmen diese Bekleidung, ergänzt durch eine entsprechende Jacke, vor allem als Nachtgewand der Männer."],"examples":[{"text":"Das alte Pyjama, das du trägst, ist voller Löcher.","reference":""},{"text":"„Sie lagen im Bett, Billie in meinem: sie hatte einen knallbunten Pyjama an, auf dem hundert Blumen blühten, jetzt sah sie aus, wie die wilde Lieblingsfrau eines Maharadschas… sie lächelte ruhig in ihr Rätselblatt.“","reference":"Kurt Tucholsky ^(→ WP): Schloß Gripsholm. In: Projekt Gutenberg-DE. Viertes Kapitel (URL) . Alte Version im Internet-Archiv abrufbar. *"},{"text":"„Selbst ohne Uniform, in gestreiften Pyjamas und Pantoffeln, bewegten sie sich anders als Zivilisten.“","reference":"Wladimir Kaminer: Onkel Wanja kommt. Eine Reise durch die Nacht. Goldmann, München 2014, ISBN 978-3-442-47364-9 , Seite 156."},{"text":"„Nach einer Weile wendet sie die Pyjamas um.“","reference":"James Salter: Ein Spiel und ein Zeitvertreib. Roman. Rowohlt Taschenbuch Verlag, Reinbek 2000, ISBN 3-499-22440-2, Seite 63."},{"text":"„Ihr Pyjama bestand aus einer schwarzen, eng geschnittenen Samthose und einer bunt bemalten, rotseidenen Jacke mit Gürtel.“","reference":"Robert Baur: Blutmai. Roman. Gmeiner, Meßkirch 2018, ISBN 978-3-8392-2290-4, Seite 103."}],"idioms":[],"collocations":[],"derivations":["Pyjamahose","Pyjamajacke","Pyjamaoberteil","Pyjamaparty","Pyjama-Party"],"sourceIds":["wiktionary","hyphenation","openthesaurus"],"sourceWord":"Pyjama","id":"e902a6d0526229"},"0070-0079:0a08362821ab52":{"word":"Pyruvat","partOfSpeech":"Substantiv","gender":"das","hyphenation":{"de-CH":"Py·ru·vat","de-DE":"Py·ru·vat"},"forms":[{"form":"Pyruvat","tags":["Nominativ","Singular"]},{"form":"Pyruvate","tags":["Nominativ","Plural"]},{"form":"Pyruvats","tags":["Genitiv","Singular"]},{"form":"Pyruvaten","tags":["Dativ","Plural"]},{"form":"Pyruvates","tags":["Genitiv","Singular"]}],"senses":[{"definition":"Salz, welches das Anion der Brenztraubensäure enthält"}],"synonyms":[],"origins":[],"examples":[{"text":"Pyruvat ist ein Zwischenprodukt der Glykolyse.","reference":""}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Pyruvat","id":"0a08362821ab52"},"0070-0079:c95ca455834f98":{"word":"Pylon","partOfSpeech":"Substantiv","gender":"der","hyphenation":{"de-CH":"Py·lon","de-DE":"Py·lon"},"forms":[{"form":"Pylon","tags":["Nominativ","Singular"]},{"form":"Pylone","tags":["Nominativ","Plural"]},{"form":"Pylons","tags":["Genitiv","Singular"]},{"form":"Pylonen","tags":["Nominativ","Plural"]}],"senses":[{"definition":"bewegliches, kegelförmiges Verkehrszeichen zur Absperrung"},{"definition":"Eingangstor altägyptischer Tempel oder Paläste mit festungsartigen Türmen"},{"definition":"Pfeiler von Hänge- oder Tragseilbrücken"}],"synonyms":["Haberkornhütchen","Leitkegel","Lübecker Hut","Lübecker Hütchen","Molankegel","Verkehrshütchen","Verkehrsleitkegel","Verkehrstöggel"],"origins":["von griechisch πυλών (pylōn^☆) ^(→ grc) „Tor, Portal, Turm“"],"examples":[{"text":"Mit einem Pylon kann man Bereiche, die vorübergehend nicht befahren werden sollen, markieren.","reference":""},{"text":"„Der Tempel wächst zuerst auf einer West-Ost-Achse im Wechsel von Höfen […], reliefgeschmückten Festhallen und sechs Pylonen, doppeltürmigen Torbauten mit schrägen Außenmauern; […].“","reference":"nach: Günter Baumann: Meisterwerke der Architektur. 3. Auflage. Reclam, Stuttgart 2007, ISBN 978-3-15-018525-4 , Seite 21, \"Amun-Tempel, Karnak\""},{"text":"„Favorisiert wird eine 65 Meter hohe Schrägseilbrücke mit vier 280 Meter hohen Pylonen, deren Stahltrossen eine vierspurige Autobahn und zwei Bahngleise halten sollen - aus Sicht der Dänen ein ‚Jahrhundertprojekt‘.“","reference":"Philip Bethge: Brückenschlag in die Provinz. In: DER SPIEGEL 25, 2009, Seite 34-35, Zitat Seite 34."}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation","openthesaurus"],"sourceWord":"Pylon","id":"c95ca455834f98"},"0070-0079:bee7e7dafcb8eb":{"word":"pyroklastisch","partOfSpeech":"Adjektiv","gender":"","hyphenation":{"de-CH":"py·ro·klas·tisch","de-DE":"py·ro·klas·tisch"},"forms":[{"form":"pyroklastisch","tags":["Positiv"]},{"form":"pyroklastische","tags":["Positiv","Nominativ","strong","Singular","feminine"]},{"form":"pyroklastischem","tags":["Positiv","Dativ","strong","Singular","masculine"]},{"form":"pyroklastischen","tags":["Positiv","Genitiv","strong","Singular","masculine"]},{"form":"pyroklastischer","tags":["Positiv","Nominativ","strong","Singular","masculine"]},{"form":"pyroklastisches","tags":["Positiv","Nominativ","strong","Singular","neuter"]},{"form":"er ist pyroklastisch","tags":["Positiv","predicative","Singular","masculine"]},{"form":"es ist pyroklastisch","tags":["Positiv","predicative","Singular","neuter"]},{"form":"sie ist pyroklastisch","tags":["Positiv","predicative","Singular","feminine"]},{"form":"sie sind pyroklastisch","tags":["Positiv","predicative","Plural"]}],"senses":[{"definition":"aus heißen, rasend schnell talwärts strömenden Gasen, Asche und klastischem Gestein (Trümmergestein) vulkanischen Ursprungs bestehend"}],"synonyms":[],"origins":["aus dem Altgriechischen πῦρ (pyr^☆) ^(→ grc) „Feuer“ und κλαστός (klastos^☆) ^(→ grc) „zerbrochen“ abgeleitetes Kunstwort, das 1902 beim Ausbruch des Mont Pelé erstmals verwendet wurde"],"examples":[{"text":"Typische Vertreter von pyroklastischen Gesteinen sind Tuff und Bimsstein.","reference":""},{"text":"Schon an der nördlichen Stadtmauer Pompejis liefen die beiden in die nächste Attacke des Vulkans: Die kollabierende Eruptionssäule drückte pyroklastische Ströme die Hänge des Vesuv hinab – glutheiße Gasschwaden, gemischt mit zersprühter Lava, deren Wucht ganze Mauern um Meter versetzte.","reference":"Tobias Hürter: Der Jahrtausendknall. In: Zeit Online. Nummer 16/2003, 10. April 2003, ISSN 0044-2070 (URL, abgerufen am 19. Dezember 2011) ."},{"text":"Diese pyroklastischen Ströme sind über 800 Grad heiß und schneller als ein Formel-1-Rennwagen.","reference":"Urs Willmann: Vulkane: Pfropf im Berg. In: Zeit Online. Nummer 16/2003, 10. April 2003, ISSN 0044-2070 (URL, abgerufen am 19. Dezember 2011) ."}],"idioms":[],"collocations":[],"derivations":["Pyroplastika","Pyroklaste"],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"pyroklastisch","id":"bee7e7dafcb8eb"},"0070-0079:12d1f2e6d84fbd":{"word":"Pyrografie","partOfSpeech":"Substantiv","gender":"die","hyphenation":{"de-CH":"Py·ro·gra·fie","de-DE":"Py·ro·gra·fie"},"forms":[{"form":"Pyrografie","tags":["Nominativ","Singular"]},{"form":"Pyrographie","tags":["alternative"]}],"senses":[{"definition":"eine Maltechnik, bei der mit einem durch einen Brenner glühend gemachten Stahl- oder Platinstift auf Holz gezeichnet wird"}],"synonyms":[],"origins":[],"examples":[{"text":"Die Pyrografie wurde im Biedermeier häufig zur Verzierung von Stuhllehnen angewandt.","reference":""}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Pyrografie","id":"12d1f2e6d84fbd"},"0070-0079:589b54ff9437b1":{"word":"Pyrographie","partOfSpeech":"Substantiv","gender":"die","hyphenation":{"de-CH":"Py·ro·gra·phie","de-DE":"Py·ro·gra·phie"},"forms":[{"form":"Pyrographie","tags":["Nominativ","Singular"]}],"senses":[{"definition":"eine Maltechnik, bei der mit einem durch einen Brenner glühend gemachten Stahl- oder Platinstift auf Holz gezeichnet wird"}],"synonyms":[],"origins":[],"examples":[],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Pyrographie","id":"589b54ff9437b1"},"0070-0079:3336bb086979f5":{"word":"Pyropiktur","partOfSpeech":"Substantiv","gender":"die","hyphenation":{"de-CH":"Py·ro·p·ik·tur","de-DE":"Py·ro·p·ik·tur"},"forms":[{"form":"Pyropiktur","tags":["Nominativ","Singular"]}],"senses":[{"definition":"das maschinelle Pressen einer Holzplatte durch zwei heiße, mit reliefartigen Mustern versehenen Walzen, bei dem Muster auf das Holz gebrannt werden"}],"synonyms":[],"origins":[],"examples":[{"text":"„Das maschinelle Pressen einer Holzplatte beim Gang durch 2 heiße, mit reliefartigen Mustern versehene Walzen heißt Pyropiktur.“","reference":"Harald Olbrich et al. (Herausgeber): Lexikon der Kunst. Architektur, Bildende Kunst, Angewandte Kunst, Industrieformgestaltung, Kunsttheorie - Begründet von Gerhard Strauß †, Herausgegeben von Harald Olbrich, Dieter Dolgner, Hubert Faensen, Peter H. Feist, Bruno Flierl, Alexander Häusler, Kurt Junghanns, Alfred Langer, Günter Meißner, Karl-Heinz Otto, Detlef Rößler und Wolfgang Schindler. CD-Rom, A - Z, Directmedia Publishing GmbH, Berlin 2004, ISBN 3-89853-443-X , Band 5, Seite 811, Artikel \"Pyrographie\""}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Pyropiktur","id":"3336bb086979f5"},"0070-0079:af7b1c5e131e7b":{"word":"pyro-","partOfSpeech":"Gebundenes Lexem","gender":"","hyphenation":{"de-CH":"pyro-","de-DE":"pyro-"},"forms":[{"form":"pyr-","tags":["variant"]}],"senses":[{"definition":"vorangestelltes Wortbildungselement mit dem Bedeutungsfeld „Feuer“, „Hitze“ und „Fieber“"}],"synonyms":[],"origins":["von dem altgriechischen Substantiv πῦρ (pyr^☆) ^(→ grc) „Feuer“"],"examples":[{"text":"Pyrotechnik beschäftigt sich mit Effekten aus Feuer und Rauch.","reference":""}],"idioms":[],"collocations":[],"derivations":["pyrogen","pyroklastisch","pyrotechnisch","Pyroelektrizität","Pyrolyse","Pyromanie","Pyromantie","Pyrometer","Pyrometrie","Pyrophobie","Pyrophor","Pyrophyt","Pyrosphäre","Pyrotechnik"],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"pyro-","id":"af7b1c5e131e7b"},"0070-0079:d38e35ee127524":{"word":"pyr-","partOfSpeech":"Gebundenes Lexem","gender":"","hyphenation":{"de-CH":"pyr-","de-DE":"pyr-"},"forms":[],"senses":[{"definition":"Alternative Schreibweise von pyro- vor Vokalen"}],"synonyms":[],"origins":[],"examples":[],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"pyr-","id":"d38e35ee127524"},"0070-0079:ff5351c2a4c67a":{"word":"Pyropissit","partOfSpeech":"Substantiv","gender":"der","hyphenation":{"de-CH":"Py·ro·pis·sit","de-DE":"Py·ro·pis·sit"},"forms":[{"form":"Pyropissit","tags":["Nominativ","Singular"]},{"form":"Pyropissits","tags":["Genitiv","Singular"]},{"form":"Pyropissites","tags":["Genitiv","Singular"]}],"senses":[{"definition":"eine Braunkohle, die zur Gewinnung von Paraffin genutzt wird"}],"synonyms":[],"origins":[],"examples":[{"text":"Pyropissit ist eine Braunkohle, die zur Gewinnung von Paraffin genutzt wird.","reference":""}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Pyropissit","id":"ff5351c2a4c67a"},"0070-0079:eb637a7204a86a":{"word":"Pyrolyse","partOfSpeech":"Substantiv","gender":"die","hyphenation":{"de-CH":"Py·ro·ly·se","de-DE":"Py·ro·ly·se"},"forms":[{"form":"Pyrolyse","tags":["Nominativ","Singular"]},{"form":"Pyrolysen","tags":["Nominativ","Plural"]}],"senses":[{"definition":"die Zersetzung von Stoffen durch Hitze"}],"synonyms":["pyrolytische Zersetzung"],"origins":["Kompositum aus den gebundenen Lexemen pyro- und -lyse"],"examples":[],"idioms":[],"collocations":[],"derivations":["Pyrolysebenzin","Pyrolysegas","Pyrolyseöl"],"sourceIds":["wiktionary","hyphenation","openthesaurus"],"sourceWord":"Pyrolyse","id":"eb637a7204a86a"},"0070-0079:a5e4dbe787f15a":{"word":"Pyrometer","partOfSpeech":"Substantiv","gender":"das","hyphenation":{"de-CH":"Py·ro·me·ter","de-DE":"Py·ro·me·ter"},"forms":[{"form":"Pyrometer","tags":["Nominativ","Singular"]},{"form":"Pyrometern","tags":["Dativ","Plural"]},{"form":"Pyrometers","tags":["Genitiv","Singular"]}],"senses":[{"definition":"Gerät, um hohe Temperaturen, die sogenannte Glühhitze, zu messen"}],"synonyms":["Strahlungsthermometer"],"origins":["Wortverbindung aus dem gebundenen Lexem pyro- und dem Substantiv Meter (im Sinne eines Messgerätes)"],"examples":[{"text":"„Die Hitze könnte zwar nach dem Pyrometer regulirt werden; man darf sich aber nicht lediglich auf diesen verlassen.“","reference":"Friedrich Kretschmar: Der haeusliche und technische Werth der Verbrennungsoefen ausfuehrlich dargestellt. Walter de Gruyter GmbH & Co KG, 2019, ISBN 978-3-11-149319-0, Seite 397 (Zitiert nach Google Books)"},{"text":"„Ist dem Pyrometer ein Ampèremeter beigefügt, so ist seine Stromanzeige gesondert zu prüfen.“","reference":"F. Henning: Temperaturmessung. Springer-Verlag, 2013, ISBN 978-3-642-81138-8, Seite 196 (Zitiert nach Google Books)"},{"text":"„Bei der Messung der Kathodentemperatur mit dem Pyrometer ist vor allem die Abkühlung der Kathodenenden als Fehlerquelle zu berücksichtigen.“","reference":"Max Knoll, Joseph Eichmeier: Technische Elektronik. Springer-Verlag, 2013, ISBN 978-3-642-92902-1, Seite 38 (Zitiert nach Google Books)"}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation","openthesaurus"],"sourceWord":"Pyrometer","id":"a5e4dbe787f15a"},"0070-0079:9903191a9915a8":{"word":"Pyroskop","partOfSpeech":"Substantiv","gender":"das","hyphenation":{"de-CH":"Py·ro·skop","de-DE":"Py·ro·skop"},"forms":[{"form":"Pyroskop","tags":["Nominativ","Singular"]},{"form":"Pyroskope","tags":["Nominativ","Plural"]},{"form":"Pyroskops","tags":["Genitiv","Singular"]},{"form":"Pyroskopen","tags":["Dativ","Plural"]},{"form":"Pyroskopes","tags":["Genitiv","Singular"]}],"senses":[{"definition":"ein Gerät, um hohe Temperaturen, die sogenannte Glühhitze, zu messen"}],"synonyms":[],"origins":["Kompositum aus den gebundenen Lexemen pyro- und -skop"],"examples":[{"text":"Durch den minder gebräuchlichen Ausdruck Pyroskop bezeichnet man Werkzeuge, welche das Vorhandenseyn höherer Hitzegrade anzeigen. (1834)","reference":"Fehlender Parameter (Hilfe) Abgerufen am 10. Dezember 2015."}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Pyroskop","id":"9903191a9915a8"},"0070-0079:b57ba4943394d2":{"word":"Python","partOfSpeech":"Substantiv","gender":"die","hyphenation":{"de-CH":"Py·thon","de-DE":"Py·thon"},"forms":[{"form":"Python","tags":["Nominativ","Singular"]},{"form":"Pythons","tags":["Nominativ","Plural"]}],"senses":[{"definition":"Schlange aus der Familie Pythonidae"},{"definition":"Vertreter der gleichnamigen Gattung aus der Familie der Pythons^([1])"},{"definition":"Name einer Open-Source-Scriptsprache"}],"synonyms":["Pythonschlange"],"origins":["nach dem schlangenartigen Drachen Python aus der griechischen Mythologie","nach der britischen Komödiantengruppe Monty Python"],"examples":[{"text":"Die größten Pythons können Längen von über 10 Metern erreichen, manche Arten werden aber kaum einen Meter lang.","reference":""},{"text":"Pythons sind überwiegend nachtaktiv.","reference":""},{"text":"„Auch wer in der Stadt einen Python tötet, muss mit der Todesstrafe rechnen.“","reference":"Sebastian Kretz: Küste der Verdammten. In: GeoEpoche: Afrika 1415-1960. Nummer Heft 66, 2014 , Seite 58-71, Zitat Seite 60."},{"text":"Python 2 ist auf dem Mac für den Einstieg immer noch die bessere Wahl.","reference":""},{"text":"„Das macht man nicht mit Maus oder Tastatur, sondern mit Programmierbefehlen in Python oder Javascript, zwei sehr verbreiteten Programmiersprachen.“","reference":"Wo man online programmieren lernen kann. Abgerufen am 28. März 2020."},{"text":"„Debian und Ubuntu planen die Entfernung von Paketen auf der Basis von Python 2. Der Support für Python 2 endet am 31. Dezember 2019.“","reference":""},{"text":"„Python 3 wurde bereits 2008 eingeführt […].“","reference":""},{"text":"„In der wenigen verbleibenden Zeit bis zur offiziellen Einstellung von Python 2 arbeiten beide Projekte daran, Pakete auf Python 3 umzustellen, wo dies möglich ist.“","reference":""},{"text":"„Python kennt einige Frameworks, die die notwendige Kommunikationsinfrastruktur automatisch erzeugen.“","reference":"Rainer Grimm: Python meets C/C++, Teil 2: SWIG und pybind11. heise.de/tp/, Heise Medien GmbH & Co. KG, Hannover, Deutschland, 10. August 2021, abgerufen am 23. August 2021."},{"text":"„Einführung in Machine Learning mit Python – Wir zeigen an Beispieldaten, wie man ein Machine-Learning-Projekt in Python umsetzt.“","reference":"Armas Scharpegge, Arnd Scharpegge: Einführung in Machine Learning mit Python. heise.de/tp/, Heise Medien GmbH & Co. KG, Hannover, Deutschland, 9. August 2021, abgerufen am 23. August 2021."},{"text":"„Die Programmiersprache Python ist zum Schweizer Taschenmesser für Data Scientists geworden.“","reference":"Jonas Volkert: iX-Workshop: Data Science mit Python. heise.de/tp/, Heise Medien GmbH & Co. KG, Hannover, Deutschland, 5. August 2021, abgerufen am 23. August 2021."},{"text":"„Python gilt aufgrund seiner Einfachheit in \"professionellen\" Entwicklerkreisen häufig nicht als Programmiersprache der Wahl […].“","reference":"Tam Hanna: Buchbesprechung: Practical Python Data Visualization für eine solide Basis. heise.de/tp/, Heise Medien GmbH & Co. KG, Hannover, Deutschland, 2. Juli 2021, abgerufen am 23. August 2021."}],"idioms":[],"collocations":[],"derivations":["Pythonanwendung","Pythoncode","Pythongrundkenntnisse","Python-IDE","Pythonkenntnisse","Pythonmodul","Pythonpackage","Pythonpaket","Pythonversion","Python-basiert"],"sourceIds":["wiktionary","hyphenation","openthesaurus"],"sourceWord":"Python","id":"b57ba4943394d2"},"0070-0079:9777016d960cc9":{"word":"Pyrotechnik","partOfSpeech":"Substantiv","gender":"die","hyphenation":{"de-CH":"Py·ro·tech·nik","de-DE":"Py·ro·tech·nik"},"forms":[{"form":"Pyrotechnik","tags":["Nominativ","Singular"]},{"form":"Pyrotechniken","tags":["Nominativ","Plural"]}],"senses":[{"definition":"die Kunst der Herstellung und Verwendung von Feuerwerkskörpern und anderen Explosivstoffen"}],"synonyms":[],"origins":[],"examples":[{"text":"„Auf den Dächern erscheinen Vermummte, die den Demozug mit Pyrotechnik empfangen.“","reference":"Gabriel Rinaldi: »Der Angriff startet, verpisst euch«. In: Spiegel Online. 17. Juni 2021, ISSN 0038-7452 (URL, abgerufen am 18. Juni 2021) ."}],"idioms":[],"collocations":[],"derivations":["pyrotechnisch","Pyrotechniker"],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Pyrotechnik","id":"9777016d960cc9"},"0070-0079:4f15a435431f51":{"word":"Pyroxenit","partOfSpeech":"Substantiv","gender":"der","hyphenation":{"de-CH":"Py·ro·xe·nit","de-DE":"Py·ro·xe·nit"},"forms":[{"form":"Pyroxenit","tags":["Nominativ","Singular"]},{"form":"Pyroxenite","tags":["Nominativ","Plural"]},{"form":"Pyroxenits","tags":["Genitiv","Singular"]},{"form":"Pyroxeniten","tags":["Dativ","Plural"]}],"senses":[{"definition":"seltenes, dunkles, magmatisches Gestein"}],"synonyms":[],"origins":[],"examples":[{"text":"„Innerhalb desselben Alkaligesteinskomplexes liegt außerdem die weltgrößte magmatische Phosphat-Lagerstätte. Dort wird apatitreicher Pyroxenit abgebaut.“","reference":"Wikipedia-Artikel „Karbonatit“"}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Pyroxenit","id":"4f15a435431f51"},"0070-0079:5c166e5366bd0a":{"word":"pythonesk","partOfSpeech":"Adjektiv","gender":"","hyphenation":{"de-CH":"py·tho·nesk","de-DE":"py·tho·nesk"},"forms":[{"form":"pythonesk","tags":["Positiv"]},{"form":"pythoneske","tags":["Positiv","Nominativ","strong","Singular","feminine"]},{"form":"pythoneskem","tags":["Positiv","Dativ","strong","Singular","masculine"]},{"form":"pythonesken","tags":["Positiv","Genitiv","strong","Singular","masculine"]},{"form":"pythonesker","tags":["Komparativ"]},{"form":"pythoneskes","tags":["Positiv","Nominativ","strong","Singular","neuter"]},{"form":"er ist pythonesk","tags":["Positiv","predicative","Singular","masculine"]},{"form":"es ist pythonesk","tags":["Positiv","predicative","Singular","neuter"]},{"form":"am pythoneskesten","tags":["Superlativ"]},{"form":"sie ist pythonesk","tags":["Positiv","predicative","Singular","feminine"]},{"form":"sie sind pythonesk","tags":["Positiv","predicative","Plural"]}],"senses":[{"definition":"im Stil Monty Pythons"}],"synonyms":[],"origins":["Ableitung (Derivation) zu Python mit dem Derivatem (Ableitungsmorphem) -esk"],"examples":[{"text":"„In Anlehnung an den Ausdruck „kafkaesk“ wurde diese Stilrichtung auch als „pythonesk“ bezeichnet.“","reference":"Wikipedia-Artikel „Monty Python“ (Stabilversion)"},{"text":"Die bittere Ironie und der schwarze Humor, mit dem Gilliam den Fortschritt als Rückschritt konnotiert, kann man in Anlehnung an Monty Python durchaus als „pythonesk“ bezeichnen.","reference":"Parfen Laszig: Blade Runner, Matrix und Avatare. Psychoanalytische Betrachtungen virtueller Wesen und Welten im Film. Springer-Verlag, 2012, ISBN 9783642256257, Seite 112 (zitiert nach Google Books) ."},{"text":"Die Spaßmacher von Monty Python prägten den Humor vor der Jahrtausendwende so nachhaltig, dass der Begriff „pythonesk“ sogar in die Wörterbücher gelangte – und dort einen surrealen und absurden Humor bezeichnet.","reference":"Stephen H. Segal: Die Weisheit der Nerds: Monty Python. Tor Online, 14. September 2016, abgerufen am 27. Februar 2017."},{"text":"Grahams Autobiografie hat alles, was die Bezeichnung pythonesk ausmacht: Schrägen, schwarzen, krassen Humor, absurde Szenen ohne Pointe, grafische Elemente, fantastische Einschübe und gleichzeitig etwas sehr Gebildetes und Britisches.","reference":"Klappentext zu „Autobiografie eines Lügners“. www.weltbild.ch, 2017, abgerufen am 27. Februar 2017."},{"text":"Das restliche Stück ist so gar nicht pythonesk, sondern eine gut durchdachte Geschichte – über das Leben.","reference":"Veronika Schmidt: Kabarett: Vitus Wieser macht seine Sache gut. In: DiePresse.com. 12. Oktober 2016, ISSN 1563-5449 (URL, abgerufen am 27. Februar 2017) ."}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"pythonesk","id":"5c166e5366bd0a"},"0070-0079:a0da721889f738":{"word":"Pythagoras","partOfSpeech":"Eigenname","gender":"der","hyphenation":{"de-CH":"Py·tha·go·ras","de-DE":"Py·tha·go·ras"},"forms":[{"form":"Pythagoras’","tags":["Genitiv","Singular"]},{"form":"des Pythagoras","tags":["Genitiv","Singular"]},{"form":"(dem) Pythagoras","tags":["Dativ","Singular"]},{"form":"(den) Pythagoras","tags":["Akkusativ","Singular"]},{"form":"(der) Pythagoras","tags":["Nominativ","Singular"]}],"senses":[{"definition":"männlicher Name, meist der griechische Philosoph Pythagoras von Samos"}],"synonyms":[],"origins":[],"examples":[{"text":"„In der Spätantike und im Mittelalter war die Überzeugung allgemein verbreitet, Pythagoras sei der Begründer der Mathematik gewesen.“","reference":"Wikipedia-Artikel „Pythagoras“ (Stabilversion)"},{"text":"„Insbesondere Pythagoras hatte durch seine Schule in Kroton in Unteritalien einen großen Einfluss auf die weitere Entwicklung der griechischen Mathematik.“","reference":"Albrecht Beutelspacher: Zahlen. Geschichte, Gesetze, Geheimnisse. C.H. Beck, München 2013, ISBN 978-3-406-64871-7, Seite 12."}],"idioms":[],"collocations":[],"derivations":["pythagoräisch","pythagoreisch"],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Pythagoras","id":"a0da721889f738"},"0070-0079:d650962033ca1f":{"word":"Pythagoras","partOfSpeech":"Substantiv","gender":"der","hyphenation":{"de-CH":"Py·tha·go·ras","de-DE":"Py·tha·go·ras"},"forms":[{"form":"Pythagoras","tags":["Nominativ","Singular"]}],"senses":[{"definition":"Satz des Pythagoras, pythagoreischer Lehrsatz"}],"synonyms":[],"origins":[],"examples":[{"text":"Du musst den Pythagoras anwenden, um die Seite c dieses rechtwinkligen Dreiecks zu berechnen.","reference":""}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Pythagoras","id":"d650962033ca1f"},"0070-0079:977eaa35488ba0":{"word":"Pythagoreer","partOfSpeech":"Substantiv","gender":"der","hyphenation":{"de-CH":"Py·tha·go·re·er","de-DE":"Py·tha·go·re·er"},"forms":[{"form":"Pythagoreer","tags":["Nominativ","Singular"]},{"form":"Pythagoräer","tags":["variant"]},{"form":"Pythagoreern","tags":["Dativ","Plural"]},{"form":"Pythagoreers","tags":["Genitiv","Singular"]}],"senses":[{"definition":"Anhänger der philosophischen Lehre des altgriechischen Philosophen Pythagoras von Samos"}],"synonyms":[],"origins":["Ableitung vom Stamm des Namens Pythagoras mit dem Gleitlaut -e- und dem Derivatem (Ableitungsmorphem) -er"],"examples":[{"text":"„Um 389/388 unternahm Platon seine erste Sizilienreise. Zunächst fuhr er nach Unteritalien, wo im 5. Jahrhundert die Philosophengemeinschaft der Pythagoreer großen Einfluss erlangt hatte, dann aber in blutigen Unruhen stark geschwächt worden war.“","reference":"Wikipedia-Artikel „Platon“ (Stabilversion)"},{"text":"„Die Pythagoreer waren davon überzeugt, daß der Weltschöpfer die Welt nach einem geometrischen Muster entworfen und mittels Zahlen geordnet hat.“","reference":"Knut Radbruch: Mathematik in den Geisteswissenschaften. Vandenhoeck & Ruprecht, Göttingen 1989, ISBN 3-525-33552-0, Seite 12."}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Pythagoreer","id":"977eaa35488ba0"},"0070-0079:13f3f4e1429ed5":{"word":"Pyramidion","partOfSpeech":"Substantiv","gender":"das","hyphenation":{"de-CH":"Py·ra·mi·d·ion","de-DE":"Py·ra·mi·d·ion"},"forms":[{"form":"Pyramidia","tags":["Nominativ","Plural"]},{"form":"Pyramidien","tags":["Nominativ","Plural"]},{"form":"Pyramidion","tags":["Nominativ","Singular"]},{"form":"Pyramidions","tags":["Genitiv","Singular"]}],"senses":[{"definition":"pyramidenförmiger Abschlussstein eines Obelisken oder einer Pyramide"}],"synonyms":[],"origins":["Bei Pyramidion handelt es sich um ein modernes Kunstwort, das den Diminutiv von πυραμίς (pyramis^☆) ^(→ grc) ‚Pyramide‘ darstellt."],"examples":[{"text":"„Diesem Steinraub fielen auch die Spitze der Pyramide, das Pyramidion, und die obersten Lagen zum Opfer.“","reference":"Hans Reichardt: Die sieben Weltwunder. Tessloff Verlag, Nürnberg 1999, ISBN 978-3-7886-0421-9, Seite 14 (Google Books) ."},{"text":"„Durch seine hellere messingähnliche Farbe wurde das Elektrum noch glänzender als das reine Gold. Dies war vielleicht der Grund, warum die Pyramidien der Obelisken mit Elektrum überzogen wurden.“","reference":"Lepsius: Über einige Aegyptische Kunstformen und ihre Entwicklung. In: Philologische und historische Abhandlungen der Königlichen Akademie der Wissenschaften zu Berlin. Ferdinand Dümmler’s Verlags-Buchhandlung, Berlin 1872, Seite 48 (Google Books) ."},{"text":"„Die Pyramidia an der Spitze der Hatschepsut-Obelisken waren mit derselben Darstellung geschmückt, die sich allerdings auf die beiden Hauptpersonen beschränkte, Amon und die Königin […].“","reference":"Christiane Desroches Noblecourt: Hatschepsut. Die geheimnisvolle Königin auf dem Pharaonenthron. Verlagsgruppe Lübbe GmbH & Co. KG, Bergisch Gladbach 2007, ISBN 978-3-404-64224-3, Seite 412 (Google Books) ."},{"text":"„Die Abwesenheit von Hieroglyphen auf denselben Flächen, von denen die Pyramidien von Granit gewöhnlich bedeckt sind, und besonders das Muster der beiden Obelisken von Heliopolis, von denen wir sprechen werden, sind Thatsachen, welche große Wahrscheinlichkeiten begründen, um anzunehmen, daß die beiden Obelisken von Luxor mit Außenwerken von Erz gekrönt waren.“","reference":"J. J. Hittorff: Ueber das Pyramidion von vergoldetem Erz, von den alten Egyptiern bei einigen ihrer Obelisken als Krönung angewendet. In: Ludwig Förster (Herausgeber): Allgemeine Bauzeitung mit Abbildungen für Architekten, Ingenieurs, Dekorateurs, Bauprofessionisten, Oekonomen, Bauunternehmer und Alle, die an den Fortschritten und Leistungen der neuesten Zeit in der Baukunst und den dahin einschlagenden Fächern Antheil nehmen. Nummer 35, Wien 1837, Seite 290 (Google Books) ."},{"text":"„Ein Charakteristikum dieser späten Pyramiden ist das Fehlen einer eigenen Spitze, des Pyramidions.“","reference":"Peter Jánosi: Die Pyramiden. Mythos und Archäologie. 2., durchgesehene und aktualisierte Auflage. C.H. Beck, München 2010, ISBN 978-3-406-50831-8, Seite 121 (Google Books) ."}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Pyramidion","id":"13f3f4e1429ed5"},"0070-0079:2fad4fb8ffdb80":{"word":"Pyromane","partOfSpeech":"Substantiv","gender":"der","hyphenation":{"de-CH":"Py·ro·ma·ne","de-DE":"Py·ro·ma·ne"},"forms":[{"form":"Pyromane","tags":["Nominativ","Singular"]},{"form":"Pyromanen","tags":["Nominativ","Plural"]},{"form":"Pyromanin","tags":["feminine"]}],"senses":[{"definition":"Person, die zwanghaft Brände legt"}],"synonyms":["Brandleger","Brandstifter","Feuerleger","Feuerteufel","Zündler"],"origins":["im 20. Jahrhundert neu gebildet aus griechisch πῦρ (pyr^☆) ^(→ grc), Genitiv πυρός (pyros^☆) ^(→ grc), „Feuer“ und griechisch μανία (mania^☆) ^(→ grc) „Raserei, Verzückung“ und dem Derivatem (Ableitungsmorphem) -e"],"examples":[{"text":"„Vom Tyne bis zum Ärmelkanal wollte niemand einen Pyromanen auf freiem Fuß wissen.“","reference":"Colleen McCullough: Insel der Verlorenen. Roman. Limes, München 2001, ISBN 3-8090-2459-7, Seite 49."}],"idioms":[],"collocations":[],"derivations":["Pyromanie","pyromanisch"],"sourceIds":["wiktionary","hyphenation","openthesaurus"],"sourceWord":"Pyromane","id":"2fad4fb8ffdb80"},"0070-0079:b40c143c896d40":{"word":"Pygmäe","partOfSpeech":"Substantiv","gender":"der","hyphenation":{"de-CH":"Pyg·mäe","de-DE":"Pyg·mäe"},"forms":[{"form":"Pygmäe","tags":["Nominativ","Singular"]},{"form":"Pygmäen","tags":["Nominativ","Plural"]},{"form":"Pygmäin","tags":["feminine"]}],"senses":[{"definition":"Angehöriger eines afrikanischen Volksgruppe, deren Kennzeichnen eine geringe Körpergröße ist"}],"synonyms":["Kleinwüchsiger","Liliputaner","Zwergmensch"],"origins":[],"examples":[{"text":"„Manche Völker im Kongo wie etwa die Pygmäen waren zwar bewundernswert friedfertig, dennoch wäre es falsch, Muster natürlicher Unschuld in ihnen zu sehen.“","reference":"Adam Hochschild: Schatten über dem Kongo. Die Geschichte eines der großen, fast vergessenen Menschheitsverbrechen. 9. Auflage. Klett-Cotta, Stuttgart 2000, ISBN 9783608947694, Seite 105"}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation","openthesaurus"],"sourceWord":"Pygmäe","id":"b40c143c896d40"},"0070-0079:7898d421a59e9f":{"word":"pyromanisch","partOfSpeech":"Adjektiv","gender":"","hyphenation":{"de-CH":"py·ro·ma·nisch","de-DE":"py·ro·ma·nisch"},"forms":[{"form":"pyromanisch","tags":["Positiv"]},{"form":"pyromanische","tags":["Positiv","Nominativ","strong","Singular","feminine"]},{"form":"pyromanischem","tags":["Positiv","Dativ","strong","Singular","masculine"]},{"form":"pyromanischen","tags":["Positiv","Genitiv","strong","Singular","masculine"]},{"form":"pyromanischer","tags":["Positiv","Nominativ","strong","Singular","masculine"]},{"form":"pyromanisches","tags":["Positiv","Nominativ","strong","Singular","neuter"]},{"form":"er ist pyromanisch","tags":["Positiv","predicative","Singular","masculine"]},{"form":"es ist pyromanisch","tags":["Positiv","predicative","Singular","neuter"]},{"form":"sie ist pyromanisch","tags":["Positiv","predicative","Singular","feminine"]},{"form":"sie sind pyromanisch","tags":["Positiv","predicative","Plural"]}],"senses":[{"definition":"die Pyromanie betreffend"}],"synonyms":[],"origins":[],"examples":[{"text":"„Die Partie hatte bereits mit zwölfminütiger Verspätung begonnen, da die Fanlager beider Vereine ihren pyromanischen Neigungen nachgehen mussten.“","reference":"Jens Trommer: Kurz vorm Abbruch. In: Märkische Allgemeine. 9./10. November 2013, Seite 8 ."}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"pyromanisch","id":"7898d421a59e9f"},"0070-0079:8ec594316d7cf7":{"word":"Pyrenäenhalbinsel","partOfSpeech":"Substantiv","gender":"die","hyphenation":{"de-CH":"Py·re·nä·en·halb·in·sel","de-DE":"Py·re·nä·en·halb·in·sel"},"forms":[{"form":"Pyrenäenhalbinsel","tags":["Nominativ","Singular"]}],"senses":[{"definition":"andere Bezeichnung für Iberien oder die Iberische Halbinsel"}],"synonyms":["iberische Halbinsel","südlich der Pyrenäen"],"origins":["Determinativkompositum, zusammengesetzt aus Pyrenäen, und Halbinsel"],"examples":[{"text":"Auf der Pyrenäenhalbinsel liegen Portugal und Spanien.","reference":""}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation","openthesaurus"],"sourceWord":"Pyrenäenhalbinsel","id":"8ec594316d7cf7"},"0070-0079:a6b2c3c249bef8":{"word":"Pyrrhichius","partOfSpeech":"Substantiv","gender":"der","hyphenation":{"de-CH":"Pyrrhi·chi·us","de-DE":"Pyrrhi·chi·us"},"forms":[{"form":"Pyrrhich","tags":["variant"]},{"form":"Pyrrhichii","tags":["Nominativ","Plural"]},{"form":"Pyrrichius","tags":["alternative"]},{"form":"Pyrrhichius","tags":["Nominativ","Singular"]}],"senses":[{"definition":"antiker Versfuß, der aus zwei kurzen Silben besteht (υ υ)"}],"synonyms":[],"origins":[],"examples":[],"idioms":[],"collocations":[],"derivations":["pyrrhichisch"],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Pyrrhichius","id":"a6b2c3c249bef8"},"0070-0079:be464c18adb502":{"word":"pyramidenförmig","partOfSpeech":"Adjektiv","gender":"","hyphenation":{"de-CH":"py·ra·mi·den·för·mig","de-DE":"py·ra·mi·den·för·mig"},"forms":[{"form":"pyramidenförmig","tags":["Positiv"]},{"form":"pyramidenförmige","tags":["Positiv","Nominativ","strong","Singular","feminine"]},{"form":"pyramidenförmigem","tags":["Positiv","Dativ","strong","Singular","masculine"]},{"form":"pyramidenförmigen","tags":["Positiv","Genitiv","strong","Singular","masculine"]},{"form":"pyramidenförmiger","tags":["Positiv","Nominativ","strong","Singular","masculine"]},{"form":"pyramidenförmiges","tags":["Positiv","Nominativ","strong","Singular","neuter"]},{"form":"er ist pyramidenförmig","tags":["Positiv","predicative","Singular","masculine"]},{"form":"es ist pyramidenförmig","tags":["Positiv","predicative","Singular","neuter"]},{"form":"sie ist pyramidenförmig","tags":["Positiv","predicative","Singular","feminine"]},{"form":"sie sind pyramidenförmig","tags":["Positiv","predicative","Plural"]}],"senses":[{"definition":"in der Form einer Pyramide; die Form einer Pyramide aufweisend"}],"synonyms":[],"origins":["Determinativkompositum aus dem Substantiv Pyramide und dem gebundenen Lexem -förmig mit dem Fugenelement -n"],"examples":[{"text":"„Fuchsbau nennen die Münchner das pyramidenförmige Apartmenthaus neben der Erlöserkirche.“","reference":"Arps langer Kampf gegen den Knall. Abgerufen am 31. März 2020."}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"pyramidenförmig","id":"be464c18adb502"},"0070-0079:7e318f60836280":{"word":"Pyramidenstumpf","partOfSpeech":"Substantiv","gender":"der","hyphenation":{"de-CH":"Py·ra·mi·den·stumpf","de-DE":"Py·ra·mi·den·stumpf"},"forms":[{"form":"Pyramidenstumpf","tags":["Nominativ","Singular"]},{"form":"Pyramidenstumpfe","tags":["Dativ","Singular"]},{"form":"Pyramidenstumpfs","tags":["Genitiv","Singular"]},{"form":"Pyramidenstümpfe","tags":["Nominativ","Plural"]},{"form":"Pyramidenstumpfes","tags":["Genitiv","Singular"]},{"form":"Pyramidenstümpfen","tags":["Dativ","Plural"]}],"senses":[{"definition":"Teil einer Pyramide unterhalb eines parallel zur Grundfläche geführten Schnittes"}],"synonyms":[],"origins":["Determinativkompositum aus Pyramide, Fugenelement -n und Stumpf"],"examples":[{"text":"„Diese Methode zur Berechnung des Volumens eines Pyramidenstumpfes stellt die aus heutiger Sicht größte mathematische Leistung der Ägypter dar.“","reference":"Die Mathematik vor den Griechen. Abgerufen am 21. Oktober 2021."}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Pyramidenstumpf","id":"7e318f60836280"},"0070-0079:7746de02db42a3":{"word":"Pykrete","partOfSpeech":"Substantiv","gender":"das","hyphenation":{"de-CH":"Py·kre·te","de-DE":"Py·kre·te"},"forms":[{"form":"Pykrete","tags":["Nominativ","Singular"]}],"senses":[{"definition":"Verbundwerkstoff, bestehend aus etwa 14 Prozent Sägemehl oder einer anderen Form feiner Holzfasern (etwa Papier) und 86 Prozent Gewichtsanteilen Wassereis"}],"synonyms":[],"origins":["Kofferwort aus dem Nachnamen Pyke und dem englischen Substantiv concrete ^(→ en)"],"examples":[{"text":"Den Militärs lagen zum Test Stäbe aus Natureis und solche aus dem neuen Material vor, das Pykrete genannt wurde.","reference":"http://www.nzz.ch/aktuell/startseite/article7YW6B-1.370102"}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Pykrete","id":"7746de02db42a3"},"0070-0079:4b8f4888277387":{"word":"pyrotechnisch","partOfSpeech":"Adjektiv","gender":"","hyphenation":{"de-CH":"py·ro·tech·nisch","de-DE":"py·ro·tech·nisch"},"forms":[{"form":"pyrotechnisch","tags":["Positiv"]},{"form":"pyrotechnische","tags":["Positiv","Nominativ","strong","Singular","feminine"]},{"form":"pyrotechnischem","tags":["Positiv","Dativ","strong","Singular","masculine"]},{"form":"pyrotechnischen","tags":["Positiv","Genitiv","strong","Singular","masculine"]},{"form":"pyrotechnischer","tags":["Positiv","Nominativ","strong","Singular","masculine"]},{"form":"pyrotechnisches","tags":["Positiv","Nominativ","strong","Singular","neuter"]},{"form":"er ist pyrotechnisch","tags":["Positiv","predicative","Singular","masculine"]},{"form":"es ist pyrotechnisch","tags":["Positiv","predicative","Singular","neuter"]},{"form":"sie ist pyrotechnisch","tags":["Positiv","predicative","Singular","feminine"]},{"form":"sie sind pyrotechnisch","tags":["Positiv","predicative","Plural"]}],"senses":[{"definition":"zur Pyrotechnik gehörend oder sie betreffend"}],"synonyms":[],"origins":["Ableitung vom Stamm des Substantivs Pyrotechnik mit dem Derivatem (Ableitungsmorphem) -isch"],"examples":[{"text":"Der ausgelöste pyrotechnische Gurtstraffer musste nach dem Unfall ersetzt werden.","reference":""}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"pyrotechnisch","id":"4b8f4888277387"},"0070-0079:ef7abc7335e56b":{"word":"Pythagoräer","partOfSpeech":"Substantiv","gender":"der","hyphenation":{"de-CH":"Py·tha·go·rä·er","de-DE":"Py·tha·go·rä·er"},"forms":[{"form":"Pythagoreer","tags":["variant"]},{"form":"Pythagoräer","tags":["Nominativ","Singular"]},{"form":"Pythagoräern","tags":["Dativ","Plural"]},{"form":"Pythagoräers","tags":["Genitiv","Singular"]}],"senses":[{"definition":"Anhänger der philosophischen Lehre des altgriechischen Philosophen Pythagoras von Samos"}],"synonyms":[],"origins":[],"examples":[{"text":"„Der Begriff Quintessenz stammt von den Pythagoräern, nach denen die klassischen vier Elemente aus einem fünften, eben der Quintessenz (von lat. quinta essentia ‚fünftes Seiendes‘), auch Äther genannt, hervorgegangen seien.“","reference":"Wikipedia-Artikel „Quintessenz (Physik)“ (Stabilversion)"},{"text":"„Für die Pythagoräer waren Zahlen nicht nur als quantitative Größen von Bedeutung, sondern sie unterschieden auch verschiedene »Qualitäten« von Zahlen.“","reference":"Albrecht Beutelspacher: Zahlen. Geschichte, Gesetze, Geheimnisse. C.H. Beck, München 2013, ISBN 978-3-406-64871-7, Seite 12."}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Pythagoräer","id":"ef7abc7335e56b"},"0070-0079:944f63c009bc4e":{"word":"Pyromanie","partOfSpeech":"Substantiv","gender":"die","hyphenation":{"de-CH":"Py·ro·ma·nie","de-DE":"Py·ro·ma·nie"},"forms":[{"form":"Pyromanie","tags":["Nominativ","Singular"]}],"senses":[{"definition":"triebhafte Brandstiftung"}],"synonyms":[],"origins":["Das Wort ist eine gelehrte Bildung aus dem gebundenen Lexem pyro- und dem Substantiv Manie."],"examples":[{"text":"„Pyromanie kommt extrem selten vor.“","reference":"Hans-Bernd Rothenhäusler, Karl-Ludwig Täschner: Kompendium Praktische Psychiatrie. und Psychotherapie. 2. Auflage. Springer-Verlag, Wien 2013, ISBN 978-3-7091-1236-6, Seite 411"},{"text":"„Der Klimahistoriker William Ruddiman von der University of Virginia hält es für möglich, dass die Folgen der Pyromanie weltweit spürbar waren.“","reference":"Johann Grolle: Verwaiste Gärten. In: SPIEGEL GESCHICHTE. Nummer 1: Die ersten Amerikaner, 2023 , Seite 48-56, Zitat Seite 54."}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Pyromanie","id":"944f63c009bc4e"},"0070-0079:cb8e98fd72dc82":{"word":"Pythonschlange","partOfSpeech":"Substantiv","gender":"die","hyphenation":{"de-CH":"Py·thon·schlan·ge","de-DE":"Py·thon·schlan·ge"},"forms":[{"form":"Python","tags":["alternative"]},{"form":"Schlange","tags":["alternative"]},{"form":"Pythonschlange","tags":["Nominativ","Singular"]},{"form":"Pythonschlangen","tags":["Nominativ","Plural"]}],"senses":[{"definition":"Angehöriger einer in Afrika, Südasien und Nordaustralien lebenden Unterordnung von fußlosen Tieren (Serpentes) aus der Familie der Pythons"}],"synonyms":["Python"],"origins":["Determinativkompositum aus Python und Schlange"],"examples":[{"text":"Zum Verbreitungsgebiet der Schnabeltiere gehören Tasmanien und die Küstenregionen der Bundesstaaten Victoria, New South Wales und Queensland. Gefahr droht ihnen von heimischen Räubern wie Greifvögeln und Pythonschlangen, aber auch von eingeschleppten Spezies wie Hunden oder Füchsen.","reference":"Armin Tima: Wussten Sie, dass...: Immer dem Schnabel nach. Wesen aus einer anderen Welt: Das Schnabeltier hat Pelz und Schwimmhäute. Wussten Sie, dass die nur in Australien heimischen Schnabeltiere eierlegende Säugetiere sind?. In: Zeit Online. 28. Dezember 2011, ISSN 0044-2070 (URL, abgerufen am 27. November 2016) ."},{"text":"Grausamer Tod: Eine Pythonschlange hat im US-Staat Florida ein zweijähriges Mädchen getötet. Die Riesenschlange brach am Mittwoch aus ihrem Terrarium aus und kroch unbemerkt ins Kinderzimmer.","reference":"Python-Attacke - \"Unsere blöde Schlange hat das Baby erwürgt\". In: stern.de. 2. Juli 2009, ISSN 0039-1239 (URL, abgerufen am 27. November 2016) ."},{"text":"Fremde Tier- und Pflanzenarten machen sich [in Florida] breit, Pythonschlangen etwa, die sich Duelle mit Alligatoren liefern.","reference":"Moritz Koch: Wo Pythonschlangen mit Alligatoren kämpfen. Floridas Everglades sind Schauplatz des weltgrößten Renaturierungsprogramms - doch das Projekt droht zu scheitern. Milliarden für den Sumpf?. In: sueddeutsche.de. 28. November 2008, ISSN 0174-4917 (URL, abgerufen am 27. November 2016) ."}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation","openthesaurus"],"sourceWord":"Pythonschlange","id":"cb8e98fd72dc82"},"0070-0079:fbac83716dd82f":{"word":"Pyromanin","partOfSpeech":"Substantiv","gender":"die","hyphenation":{"de-CH":"Py·ro·ma·nin","de-DE":"Py·ro·ma·nin"},"forms":[{"form":"Pyromane","tags":["masculine"]},{"form":"Pyromanin","tags":["Nominativ","Singular"]},{"form":"Pyromaninnen","tags":["Nominativ","Plural"]}],"senses":[{"definition":"weibliche Person, die zwanghaft Brände legt"}],"synonyms":[],"origins":["Ableitung (Motion, Movierung) des Femininums aus der männlichen Form Pyromane, Subtraktionsfuge -e und mit dem Derivatem (Ableitungsmorphem) -in"],"examples":[{"text":"„Ihr dürft mich jetzt ins Krankenhaus bringen zu den Bettnässern und der Pyromanin, drei Mahlzeiten und jemand, der mir sagt, wer in meinem Ohr atmet.“","reference":"Vielleicht Langusten. Abgerufen am 5. Dezember 2024."}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Pyromanin","id":"fbac83716dd82f"},"0070-0079:4b335a5e5d59d4":{"word":"Pyroelektrizität","partOfSpeech":"Substantiv","gender":"die","hyphenation":{"de-CH":"Py·ro·elek·tri·zi·tät","de-DE":"Py·ro·elek·tri·zi·tät"},"forms":[{"form":"Pyroelektrizität","tags":["Nominativ","Singular"]}],"senses":[{"definition":"Umstand, als Kristall unter gewissen Bedingungen (schnelle Erwärmung) Polarisationsladung (Elektrizität) zu zeigen"}],"synonyms":["pyroelektrische Polarisation","pyroelektrischer Effekt"],"origins":["Ableitung (Suffigierung) vom Adjektiv pyroelektrisch mit dem Derivatem (Ableitungsmorphem) -ität"],"examples":[{"text":"„Es gibt Kristalle, z. B. Turmalin, die bei einer Temperaturänderung eine elektrische Aufladung bestimmter Kristallflächen zeigen. Diesen Effekt nennt man Pyroelektrizität. Pyroelektrische Kristalle bauen sich aus geordneten polaren Atomgruppen auf, die sich in ihrer Wirkung überlagern und zu einer Polarisation P des Kristalles führen.“","reference":"Fehlender Parameter (Hilfe) Abgerufen am 13. Dezember 2017."}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation","openthesaurus"],"sourceWord":"Pyroelektrizität","id":"4b335a5e5d59d4"},"0070-0079:d479c5daac807d":{"word":"Pyroxen","partOfSpeech":"Substantiv","gender":"der","hyphenation":{"de-CH":"Py·ro·xen","de-DE":"Py·ro·xen"},"forms":[{"form":"Pyroxen","tags":["Nominativ","Singular"]},{"form":"Pyroxene","tags":["Nominativ","Plural"]},{"form":"Pyroxens","tags":["Genitiv","Singular"]},{"form":"Pyroxenen","tags":["Dativ","Plural"]}],"senses":[{"definition":"gesteinsbildendes Mineral"}],"synonyms":[],"origins":["Entlehnung aus dem Altgriechischen zum Adjektiv ξένος (xenos^☆) ^(→ grc) „fremd“ und dem Substantiv πῦρ (pyr^☆) ^(→ grc) „Feuer“; der Name wurde 1796 vom französischen Mineralogen René-Just Haüy ^(→ WP) für Augite vergeben, die vor der Eruption der Lava kristallisierten."],"examples":[{"text":"Alle Pyroxene sind Kettensilikate, in denen neben Silizium und Sauerstoff vor allem Magnesium, Eisen und Kalzium eine Rolle spielen.","reference":"Pyroxene im Gestein erkennen. www.kristallin.de, 10. September 2017, abgerufen am 24. Oktober 2018."},{"text":"Pyroxene haben eine Härte von etwa 5–6, sind also nicht oder nur mit Mühe ritzbar.","reference":""},{"text":"Die Pyroxene werden eingeteilt in a) Magnesium-Eisen-Pyroxene, b) Calcium-Pyroxene, c) Natrium-Pyroxene, d) Calcium-Natrium-Pyroxene, e) Lithium-Pyroxene (Spodumen) und f) Mangan-Magnesium-Pyroxene (selten).","reference":"Lexikon der Geowissenschaften: Pyroxene. In: Spektrum der Wissenschaft Online. ISSN 0170-2971 (URL, abgerufen am 24. Oktober 2018) ."},{"text":"Wegen der Bedeutung für die Zusammensetzung und den Aufbau der unteren Erdkruste und des oberen Erdmantels sind Pyroxene Gegenstand zahlreicher neuerer Untersuchungen, insbesondere zum Verhalten der Pyroxene und ihrer Strukturen bei hohen Drucken (Hochdrucksynthese).","reference":""},{"text":"Die Analyse zeigt jetzt, dass das Gestein hohe Anteile von Mineralien wie Feldspat und Pyroxen enthält, die vermutlich vulkanischer Herkunft sind.","reference":"wbr/dpa: Mars-Meteorit: Schwarze Schönheit mit heißer Vergangenheit. In: Spiegel Online. 4. Januar 2013, ISSN 0038-7452 (URL, abgerufen am 24. Oktober 2018) ."}],"idioms":[],"collocations":[],"derivations":["Pyroxenit"],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Pyroxen","id":"d479c5daac807d"},"0070-0079:87f9ff87f95fd6":{"word":"Pygmalioneffekt","partOfSpeech":"Substantiv","gender":"der","hyphenation":{"de-CH":"Pyg·ma·li·on·ef·fekt","de-DE":"Pyg·ma·li·on·ef·fekt"},"forms":[{"form":"Pygmalioneffekt","tags":["Nominativ","Singular"]},{"form":"Pygmalion-Effekt","tags":["alternative"]},{"form":"Pygmalioneffekte","tags":["Dativ","Singular"]},{"form":"Pygmalioneffekts","tags":["Genitiv","Singular"]},{"form":"Pygmalioneffektes","tags":["Genitiv","Singular"]}],"senses":[{"definition":"besseres (Lern-)Ergebnis, das erzielt wird, wenn ein Lehrer einem Schüler viel zutraut und diesen unbewusst besonders fördert"}],"synonyms":[],"origins":["Determinativkompositum aus dem Eigennamen Pygmalion und dem Substantiv Effekt"],"examples":[{"text":"„Zu den bekanntesten Untersuchungen, die sich mit der Wahrnehmung von Schülern durch Lehrer befassen, gehören die zum sogenannten ‚Pygmalioneffekt‘ […].“","reference":"Martin Fromm: Diversität in der Schule. UTB GmbH, 2019, ISBN 978-3-8252-5136-9 (Zitiert nach Google Books, Zitat Seite 44.)"},{"text":"„Auf die Schule bezogen bedeutet der sogenannte Pygmalioneffekt ganz allgemein, dass Lehrkräfte auf der Grundlage ihrer spezifischen und z. T. wenig kontrollierten Erwartungen Schülerleistungen und Schülerverhalten ‚erschaffen‘ oder ‚formen‘.“","reference":"Ingrid Hesse, Brigitte Latzko: Diagnostik für Lehrkräfte. UTB, 2017, ISBN 978-3-8252-4751-5 (Zitiert nach Google Books, Zitat Seite 48.)"},{"text":"„Der Pygmalioneffekt geht auf den Künstler Pygmalion von Zypern zurück, der eine elfenbeinfarbene weibliche Figur schafft, in die er sich immer stärker verliebt.“","reference":"Johanna F. Schwarz: Zuschreibung als wirkmächtiges Phänomen in der Schule. StudienVerlag, 2018, ISBN 978-3-7065-5966-9 (Zitiert nach Google Books, Zitat Seite 9.)"},{"text":"„Beim Golemeffekt handelt es sich um einen negativen Pygmalioneffekt, d. h., negative Lehrererwartungen führen zu negativen Schülerleistungen.“","reference":"Markus Gerber: Pädagogische Psychologie im Sportunterricht. Meyer & Meyer, 2015, ISBN 978-3-8403-1161-1 (Zitiert nach Google Books, Zitat Seite 259.)"}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Pygmalioneffekt","id":"87f9ff87f95fd6"},"0070-0079:cb9ecc27522638":{"word":"Pygmalion-Effekt","partOfSpeech":"Substantiv","gender":"","hyphenation":{"de-CH":"Pyg·ma·li·on-Ef·fekt","de-DE":"Pyg·ma·li·on-Ef·fekt"},"forms":[{"form":"Pygmalioneffekt","tags":["alternative"]},{"form":"Pygmalion-Effekt","tags":["Nominativ","Singular"]},{"form":"Pygmalion-Effekte","tags":["Dativ","Singular"]},{"form":"Pygmalion-Effekts","tags":["Genitiv","Singular"]},{"form":"Pygmalion-Effektes","tags":["Genitiv","Singular"]}],"senses":[{"definition":"besseres (Lern-)Ergebnis, das erzielt wird, wenn ein Lehrer einem Schüler viel zutraut und diesen unbewusst besonders fördert"}],"synonyms":["Rosenthal-Effekt"],"origins":[],"examples":[{"text":"„Über das Vorgehen und die Wirkungen von professionellem Feedback wurden bereits so viele Bücher geschrieben, dass wir es vorziehen, uns auf eine praxisrelevante Annäherung an das, was „Ansporn“ konkret bedeutet, zu konzentrieren. In der Forschung wird dieses Konstrukt als der ‚Pygmalion-Effekt‘ bezeichnet (nach der mythologischen Figur Pygmalion).“","reference":"Carl Naughton, Andreas Steinle: 30 Minuten Zukunftsmut. GABAL Verlag GmbH, 2019, ISBN 978-3-9562389-7-0 (Zitiert nach Google Books, Zitat Seite 76.)"},{"text":"„In der Psychologie spricht man vom sogenannten Pygmalion-Effekt‚ der sich auch erfolgreich auf den Bereich der Mitarbeiterführung übertragen lässt.“","reference":"Hanno Göpfert: Das 1x1 der modernen Mitarbeiterführung. BoD – Books on Demand, 2019, ISBN 978-3-7481-8305-1 (Zitiert nach Google Books, Zitat Seite 104.)"},{"text":"„Das hängt mit der Erwartungshaltung, dem sogenannten Pygmalion-Effekt zusammen, denn motivationsabhängige Faktoren wie Weite und Erwartungen beeinflussen stark die individuellen Ziele.“","reference":"Regina Canto: Cantamus Pädagogik & Campus. BoD – Books on Demand, 2018, ISBN 978-3-7460-9747-3 (Zitiert nach Google Books, Zitat Seite 45.)"},{"text":"„Der Pygmalion-Effekt funktioniert sehr ähnlich, aber eben nicht in der Form einer Selbstbeeinflussung, sondern er geht von einer fremden Person aus.“","reference":"Wolfgang Rupsch: Leben und Aufwachsen in einer Instant Gesellschaft. TWENTYSIX, 2017, ISBN 978-3-7407-3245-5 (Zitiert nach Google Books, Zitat Seite 47.)"}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation","openthesaurus"],"sourceWord":"Pygmalion-Effekt","id":"cb9ecc27522638"},"0070-0079:9a2192cb726ba9":{"word":"Pyurie","partOfSpeech":"Substantiv","gender":"die","hyphenation":{"de-CH":"Py·urie","de-DE":"Py·urie"},"forms":[{"form":"Pyurie","tags":["Nominativ","Singular"]},{"form":"Pyurien","tags":["Nominativ","Plural"]}],"senses":[{"definition":"das Auftreten von Eiter im Urin"}],"synonyms":[],"origins":[],"examples":[{"text":"„Findet man bei der Untersuchung einer Urinprobe Leukozyten, aber der Nachweis von Bakterien misslingt, liegt eine sterile Pyurie vor.“","reference":"Sterile Pyurie – ein häufiges Problem. In: PraxisDepesche. 2015, abgerufen am 6. Januar 2021."}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Pyurie","id":"9a2192cb726ba9"},"0070-0079:dcc8f6ebc7ab71":{"word":"Pyhrn","partOfSpeech":"Toponym","gender":"der","hyphenation":{"de-CH":"Pyhrn","de-DE":"Pyhrn"},"forms":[{"form":"Pyhrn","tags":["Nominativ","Singular"]},{"form":"Pyhrns","tags":["Genitiv","Singular"]}],"senses":[{"definition":"Pass in den Ostalpen zwischen Oberösterreich und der Steiermark"}],"synonyms":[],"origins":[],"examples":[{"text":"Aufgrund seiner geringen Höhe ist der Pyhrn bereits seit der Jungsteinzeit ein bedeutender Alpenpass.","reference":""}],"idioms":[],"collocations":[],"derivations":["Pyhrnautobahn","Pyhrnbahn","Pyhrnpass"],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Pyhrn","id":"dcc8f6ebc7ab71"},"0070-0079:692617156a2492":{"word":"Pyhra","partOfSpeech":"Toponym","gender":"das","hyphenation":{"de-CH":"Pyhra","de-DE":"Pyhra"},"forms":[{"form":"Pyhras","tags":["Genitiv","Singular"]},{"form":"des Pyhra","tags":["Genitiv","Singular"]},{"form":"des Pyhras","tags":["Genitiv","Singular"]},{"form":"(das) Pyhra","tags":["Nominativ","Singular"]},{"form":"(dem) Pyhra","tags":["Dativ","Singular"]}],"senses":[{"definition":"österreichische Gemeinde in Niederösterreich"}],"synonyms":[],"origins":[],"examples":[{"text":"Pyhra liegt östlich von St. Pölten.","reference":""}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Pyhra","id":"692617156a2492"},"0070-0079:8c3c7bf4647bf5":{"word":"pyjamaähnlich","partOfSpeech":"Adjektiv","gender":"","hyphenation":{"de-CH":"py·ja·ma·ähn·lich","de-DE":"py·ja·ma·ähn·lich"},"forms":[{"form":"pyjamaähnlich","tags":["Positiv"]},{"form":"pyjamaähnliche","tags":["Positiv","Nominativ","strong","Singular","feminine"]},{"form":"pyjamaähnlichem","tags":["Positiv","Dativ","strong","Singular","masculine"]},{"form":"pyjamaähnlichen","tags":["Positiv","Genitiv","strong","Singular","masculine"]},{"form":"pyjamaähnlicher","tags":["Positiv","Nominativ","strong","Singular","masculine"]},{"form":"pyjamaähnliches","tags":["Positiv","Nominativ","strong","Singular","neuter"]},{"form":"er ist pyjamaähnlich","tags":["Positiv","predicative","Singular","masculine"]},{"form":"es ist pyjamaähnlich","tags":["Positiv","predicative","Singular","neuter"]},{"form":"sie ist pyjamaähnlich","tags":["Positiv","predicative","Singular","feminine"]},{"form":"sie sind pyjamaähnlich","tags":["Positiv","predicative","Plural"]}],"senses":[{"definition":"wie ein Pyjama; einem Pyjama ähnelnd"}],"synonyms":[],"origins":["Determinativkompositum aus dem Substantiv Pyjama und dem Adjektiv ähnlich"],"examples":[{"text":"Das kleine Kind trägt ein pyjamaähnliches Kleid.","reference":""},{"text":"„Sie trägt einen pyjamaähnlichen Anzug aus dunkelroter Seide mit Glitzersteinen verziert und wenn sie grinst, was sie häufig tut, kommt eine unvollständige Zahnreihe zum Vorschein.“","reference":"Caroline Börger: Das neue Schön. In: Welt Online. 25. Mai 2019, ISSN 0173-8437 (URL, abgerufen am 12. April 2021) ."}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"pyjamaähnlich","id":"8c3c7bf4647bf5"},"0070-0079:9d2ba49bc32797":{"word":"pyjamaartig","partOfSpeech":"Adjektiv","gender":"","hyphenation":{"de-CH":"py·ja·ma·ar·tig","de-DE":"py·ja·ma·ar·tig"},"forms":[{"form":"pyjamaartig","tags":["Positiv"]},{"form":"pyjamaartige","tags":["Positiv","Nominativ","strong","Singular","feminine"]},{"form":"pyjamaartigem","tags":["Positiv","Dativ","strong","Singular","masculine"]},{"form":"pyjamaartigen","tags":["Positiv","Genitiv","strong","Singular","masculine"]},{"form":"pyjamaartiger","tags":["Positiv","Nominativ","strong","Singular","masculine"]},{"form":"pyjamaartiges","tags":["Positiv","Nominativ","strong","Singular","neuter"]},{"form":"er ist pyjamaartig","tags":["Positiv","predicative","Singular","masculine"]},{"form":"es ist pyjamaartig","tags":["Positiv","predicative","Singular","neuter"]},{"form":"sie ist pyjamaartig","tags":["Positiv","predicative","Singular","feminine"]},{"form":"sie sind pyjamaartig","tags":["Positiv","predicative","Plural"]}],"senses":[{"definition":"wie ein Pyjama; einem Pyjama ähnelnd"}],"synonyms":[],"origins":["Determinativkompositum aus Pyjama und dem gebundenen Lexem -artig"],"examples":[{"text":"Der Junge liebt seinen pyjamaartigen Anzug.","reference":""},{"text":"„Der Däne Henrik Vibskov arbeitet weiterhin mit wilden Mustern, Hochwasserhosen und pyjamaartigem Beinkleid.“","reference":"Enrico Ippolito: Ewiger Kreislauf. In: taz.de. 20. Januar 2013, ISSN 2626-5761 (URL, abgerufen am 12. April 2021) ."},{"text":"„Vor dem ungewöhnlichen Besuch wurden sie in letzter Minuten gewarnt, vier Frauen erscheinen in hastig herbeigeschafften, pyjamaartigen Gewändern - und stehen einer Handvoll Männer gegenüber, die nichts als Unterhosen tragen.“","reference":"Nikolaus Doll: In einem Zug entlang der Seidenstraße: Gespräche zum Eintopf, Tänze zum Tee. In: Welt Online. 20. Februar 2011, ISSN 0173-8437 (URL, abgerufen am 12. April 2021) ."}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"pyjamaartig","id":"9d2ba49bc32797"},"0070-0079:7dfa1248d12b09":{"word":"Pyroshow","partOfSpeech":"Substantiv","gender":"die","hyphenation":{"de-CH":"Py·ro·show","de-DE":"Py·ro·show"},"forms":[{"form":"Pyroshow","tags":["Nominativ","Singular"]},{"form":"Pyroshows","tags":["Nominativ","Plural"]}],"senses":[{"definition":"optisch-akustisches Spektakel aus Feuer und Rauch; künstlerische Darbietung mit Lichteffekten"}],"synonyms":[],"origins":[],"examples":[{"text":"„Eine Pyroshow samt Feuerwerk nimmt die Demonstrierenden in Empfang.“","reference":"Gabriel Rinaldi: »Der Angriff startet, verpisst euch«. In: Spiegel Online. 17. Juni 2021, ISSN 0038-7452 (URL, abgerufen am 18. Juni 2021) ."},{"text":"„Als Tristan Blackmon vor der Nordtribüne den vierten Treffer erzielte, brach die von der Liga genehmigte Pyroshow los.“","reference":"Fehlender Parameter (Hilfe) James Montague: Abgerufen am 6. Juli 2021."}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Pyroshow","id":"7dfa1248d12b09"},"0070-0079:9e565bb6a2c496":{"word":"pylisch","partOfSpeech":"Adjektiv","gender":"","hyphenation":{"de-CH":"py·lisch","de-DE":"py·lisch"},"forms":[{"form":"pylisch","tags":["Positiv"]},{"form":"pylische","tags":["Positiv","Nominativ","strong","Singular","feminine"]},{"form":"pylischem","tags":["Positiv","Dativ","strong","Singular","masculine"]},{"form":"pylischen","tags":["Positiv","Genitiv","strong","Singular","masculine"]},{"form":"pylischer","tags":["Positiv","Nominativ","strong","Singular","masculine"]},{"form":"pylisches","tags":["Positiv","Nominativ","strong","Singular","neuter"]},{"form":"er ist pylisch","tags":["Positiv","predicative","Singular","masculine"]},{"form":"es ist pylisch","tags":["Positiv","predicative","Singular","neuter"]},{"form":"sie ist pylisch","tags":["Positiv","predicative","Singular","feminine"]},{"form":"sie sind pylisch","tags":["Positiv","predicative","Plural"]}],"senses":[{"definition":"das Herrschaftsgebiet des Palastes von Pylos betreffend, zu ihm gehörend, von ihm ausgehend"}],"synonyms":[],"origins":["Derivation (Ableitung) zum Stamm des Substantivs Pylos mit dem Derivatem (Ableitungsmorphem) -isch"],"examples":[{"text":"„Den Tafeln nach teilt die pylische Verwaltung das Gebiet in eine diesseitige und eine jenseitige Provinz, getrennt durch das Gebirge Aigaleion.“","reference":"Bernhard F. Steinmann: Im Palast des Wanax. In: DAMALS. Das Magazin für Geschichte. Nummer 12, 2018, ISSN 0011-5908, Seite 30 ."}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"pylisch","id":"9e565bb6a2c496"},"0070-0079:3af95e129c520d":{"word":"Pyknometer","partOfSpeech":"Substantiv","gender":"das","hyphenation":{"de-CH":"Py·kno·me·ter","de-DE":"Py·kno·me·ter"},"forms":[{"form":"Pyknometer","tags":["Nominativ","Singular"]},{"form":"Pyknometern","tags":["Dativ","Plural"]},{"form":"Pyknometers","tags":["Genitiv","Singular"]}],"senses":[{"definition":"Instrument zur Bestimmung der Dichte von Festkörpern oder Flüssigkeiten"}],"synonyms":[],"origins":[],"examples":[{"text":"„Die Probengröße wird durch deren Art und Größe, deren Handhabbarkeit und die Größe des Pyknometers bestimmt.“","reference":"Gottfried Wilhelm Ehrenstein: Kunststoff-Schadensanalyse. Carl Hanser Verlag GmbH Co KG, 2020, ISBN 978-3-446-46844-3, Seite 40 (Zitiert nach Google Books)"},{"text":"„Für die Bestimmung der Dichte von Schichten bedient man sich oft eines Pyknometers.“","reference":"Nasser Kanani: Galvanotechnik. Carl Hanser Verlag GmbH Co KG, 2020, ISBN 978-3-446-46533-6, Seite 695 (Zitiert nach Google Books)"},{"text":"„Die Untersuchungsprobe wird in das leere und trockene Pyknometers eingewogen und danach das Pyknometer mit Eintauchflüssigkeit befüllt.“","reference":"Achim Frick, Claudia Stern: Einführung in die Kunststoffprüfung. Carl Hanser Verlag GmbH Co KG, 2017, ISBN 978-3-446-45455-2, Seite 69 (Zitiert nach Google Books)"}],"idioms":[],"collocations":[],"derivations":["Pyknometermethode"],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Pyknometer","id":"3af95e129c520d"},"0070-0079:206b1a4fd0deb3":{"word":"Pyrgeometer","partOfSpeech":"Substantiv","gender":"das","hyphenation":{"de-CH":"Pyr·geo·me·ter","de-DE":"Pyr·geo·me·ter"},"forms":[{"form":"Pyrgeometer","tags":["Nominativ","Singular"]},{"form":"Pyrgeometern","tags":["Dativ","Plural"]},{"form":"Pyrgeometers","tags":["Genitiv","Singular"]}],"senses":[{"definition":"Gerät zur Messung der atmosphärischen Wärmestrahlung, die in Richtung der Erde abgestrahlt wird"}],"synonyms":[],"origins":[],"examples":[{"text":"„Pyrgeometer sollten generell belüftet werden, um eine einheitliche Gehäusetemperatur zu gewährleisten.“","reference":"Thomas Foken: EAGLE-STARTHILFE Energieaustausch an der Erdoberfläche. BoD – Books on Demand, 2013, ISBN 978-3-937219-63-9, Seite 39 (Zitiert nach Google Books)"},{"text":"„Nach unseren Messungen mit dem Pyrgeometer beträgt die effektive Ausstrahlung Sₑ aber nie mehr als 0,2. Ein in klaren Nächten häufig vorkommender Höchstwert ist 0,15.“","reference":"Otto Wilhelm Kessler, Wolfgang Kaempfert: Die Frostschadenverhütung. Springer-Verlag, 2013, ISBN 978-3-662-02191-0, Seite 93 (Zitiert nach Google Books)"},{"text":"„Die Befürchtung Falkenbergs, daß durch den nächtlichen Temperaturfall Temperaturdifferenzen zwischen dem Pyrgeometer und der umgebenden Luft entstehen könnten, die die Ergebnisse fälschen könnten, ist durch direkte Messungen der Temperaturdifferenz zwischen Apparat und Luft nicht bestätigt worden.“","reference":"Franz Linke: Meteorologisches Taschenbuch. Akademische Verlagsgesellschaft, 1939, Seite 237 (Zitiert nach Google Books)"}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Pyrgeometer","id":"206b1a4fd0deb3"},"0070-0079:e012fb25f3214b":{"word":"Pyrheliometer","partOfSpeech":"Substantiv","gender":"das","hyphenation":{"de-CH":"Pyr·he·lio·me·ter","de-DE":"Pyr·he·lio·me·ter"},"forms":[{"form":"Pyrheliometer","tags":["Nominativ","Singular"]},{"form":"Pyrheliometern","tags":["Dativ","Plural"]},{"form":"Pyrheliometers","tags":["Genitiv","Singular"]}],"senses":[{"definition":"Instrument zur Messung der direkten Sonnenstrahlung in Watt pro Quadratmeter"}],"synonyms":[],"origins":[],"examples":[],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Pyrheliometer","id":"e012fb25f3214b"},"0070-0079:6f3c80a11f78ba":{"word":"Pyranometer","partOfSpeech":"Substantiv","gender":"das","hyphenation":{"de-CH":"Pyr·ano·me·ter","de-DE":"Pyr·ano·me·ter"},"forms":[{"form":"Pyranometer","tags":["Nominativ","Singular"]},{"form":"Pyranometern","tags":["Dativ","Plural"]},{"form":"Pyranometers","tags":["Genitiv","Singular"]}],"senses":[{"definition":"Instrument zur Messung der direkten Sonnenstrahlung"}],"synonyms":[],"origins":[],"examples":[],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Pyranometer","id":"6f3c80a11f78ba"},"0070-0079:a76c562d16d3c4":{"word":"Pyrotechniker","partOfSpeech":"Substantiv","gender":"der","hyphenation":{"de-CH":"Py·ro·tech·ni·ker","de-DE":"Py·ro·tech·ni·ker"},"forms":[{"form":"Pyrotechniker","tags":["Nominativ","Singular"]},{"form":"Pyrotechnikern","tags":["Dativ","Plural"]},{"form":"Pyrotechnikers","tags":["Genitiv","Singular"]},{"form":"Pyrotechnikerin","tags":["feminine"]}],"senses":[{"definition":"Person, die sich beruflich mit der Herstellung/Verwendung von Feuerwerkskörpern und anderen Explosivstoffen beschäftigt"}],"synonyms":[],"origins":["Ableitung vom Substantiv Pyrotechnik mit dem Derivatem (Ableitungsmorphem) -er"],"examples":[],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Pyrotechniker","id":"a76c562d16d3c4"},"0070-0079:0864987df149a6":{"word":"Pyrotechnikerin","partOfSpeech":"Substantiv","gender":"die","hyphenation":{"de-CH":"Py·ro·tech·ni·ke·rin","de-DE":"Py·ro·tech·ni·ke·rin"},"forms":[{"form":"Pyrotechniker","tags":["masculine"]},{"form":"Pyrotechnikerin","tags":["Nominativ","Singular"]},{"form":"Pyrotechnikerinnen","tags":["Nominativ","Plural"]}],"senses":[{"definition":"weibliche Person, die sich beruflich mit der Herstellung/Verwendung von Feuerwerkskörpern und anderen Explosivstoffen beschäftigt"}],"synonyms":[],"origins":["Ableitung (Motion, Movierung) des Femininums aus der männlichen Form Pyrotechniker mit dem Derivatem (Ableitungsmorphem) -in"],"examples":[],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Pyrotechnikerin","id":"0864987df149a6"},"0070-0079:cebf5600339a6f":{"word":"Pyrit","partOfSpeech":"Substantiv","gender":"der","hyphenation":{"de-CH":"Py·rit","de-DE":"Py·rit"},"forms":[{"form":"Pyrit","tags":["Nominativ","Singular"]},{"form":"Pyrite","tags":["Nominativ","Plural"]},{"form":"Pyrits","tags":["Genitiv","Singular"]},{"form":"Pyriten","tags":["Dativ","Plural"]}],"senses":[{"definition":"häufig vorkommendes, hartes Mineral, das aus Schwefel und Eisen besteht"}],"synonyms":["Eisenkies","Eisensulfid","Fe(S2)","Katzengold","Narrengold","Schwefelkies"],"origins":[],"examples":[],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation","openthesaurus"],"sourceWord":"Pyrit","id":"cebf5600339a6f"},"0070-0079:b131c41576caf8":{"word":"pyrenäisch","partOfSpeech":"Adjektiv","gender":"","hyphenation":{"de-CH":"py·re·nä·isch","de-DE":"py·re·nä·isch"},"forms":[{"form":"pyrenäisch","tags":["Positiv"]},{"form":"pyrenäische","tags":["Positiv","Nominativ","strong","Singular","feminine"]},{"form":"pyrenäischem","tags":["Positiv","Dativ","strong","Singular","masculine"]},{"form":"pyrenäischen","tags":["Positiv","Genitiv","strong","Singular","masculine"]},{"form":"pyrenäischer","tags":["Positiv","Nominativ","strong","Singular","masculine"]},{"form":"pyrenäisches","tags":["Positiv","Nominativ","strong","Singular","neuter"]},{"form":"er ist pyrenäisch","tags":["Positiv","predicative","Singular","masculine"]},{"form":"es ist pyrenäisch","tags":["Positiv","predicative","Singular","neuter"]},{"form":"sie ist pyrenäisch","tags":["Positiv","predicative","Singular","feminine"]},{"form":"sie sind pyrenäisch","tags":["Positiv","predicative","Plural"]}],"senses":[{"definition":"die Pyrenäen betreffend, zu ihnen gehörend"}],"synonyms":[],"origins":["Derivation (Ableitung) zum Stamm des Substantivs Pyrenäen mit dem Derivatem (Ableitungsmorphem) -isch"],"examples":[],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"pyrenäisch","id":"b131c41576caf8"},"0070-0079:7149985c5344cd":{"word":"Pyjamahose","partOfSpeech":"Substantiv","gender":"die","hyphenation":{"de-CH":"Py·ja·ma·ho·se","de-DE":"Py·ja·ma·ho·se"},"forms":[{"form":"Pyjamahose","tags":["Nominativ","Singular"]},{"form":"Pyjamahosen","tags":["Nominativ","Plural"]}],"senses":[{"definition":"Hose, die Teil eines Pyjamas ist"}],"synonyms":[],"origins":["Determinativkompositum aus den Substantiven Pyjama und Hose"],"examples":[{"text":"„Als er sich eben die Pyjamahose angezogen hatte, bremste der Zug heftig und legte sich gleichzeitig in eine wüste Kurve.“","reference":"Johannes Mario Simmel: Es muß nicht immer Kaviar sein. Mit auserlesenen Kochrezepten des Geheimagenten wider Willen. Nikol, Hamburg 2015, ISBN 978-3-86820-292-2, Seite 463. Erstveröffentlichung Zürich 1960."}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Pyjamahose","id":"7149985c5344cd"},"0070-0079:5779c468ddcecd":{"word":"Pyämie","partOfSpeech":"Substantiv","gender":"die","hyphenation":{"de-CH":"Py·ä·mie","de-DE":"Py·ä·mie"},"forms":[{"form":"Pyämie","tags":["Nominativ","Singular"]},{"form":"Pyämien","tags":["Nominativ","Plural"]}],"senses":[{"definition":"Form der Sepsis (Blutvergiftung), bei der Eitererreger im Blut vorhanden sind"}],"synonyms":[],"origins":[],"examples":[{"text":"„Es dauerte nicht lange, bis die Öffentlichkeit geradezu stolz auf den Mann war, dessen Erforschung der Pyämie (einer besonders gefährlichen Blutvergiftung) in Indien, der Pest in China und ähnlicher Krankheiten in anderen Ländern die Medizin bald mit einem Gegengift von umwälzender Bedeutung zu bereichern versprach.“","reference":"H.P. Lovecraft: Das letzte Experiment. In: Das Gesamtwerk: Sämtliche Erzählungen und Zusammenarbeiten. Festa, Leipzig 2020, ISBN 978-3-865-52882-7, Seite 667 ."}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Pyämie","id":"5779c468ddcecd"},"0070-0079:b8476aa0ff41f0":{"word":"pyramidenartig","partOfSpeech":"Adjektiv","gender":"","hyphenation":{"de-CH":"py·ra·mi·den·ar·tig","de-DE":"py·ra·mi·den·ar·tig"},"forms":[{"form":"pyramidenartig","tags":["Positiv"]},{"form":"pyramidenartige","tags":["Positiv","Nominativ","strong","Singular","feminine"]},{"form":"pyramidenartigem","tags":["Positiv","Dativ","strong","Singular","masculine"]},{"form":"pyramidenartigen","tags":["Positiv","Genitiv","strong","Singular","masculine"]},{"form":"pyramidenartiger","tags":["Positiv","Nominativ","strong","Singular","masculine"]},{"form":"pyramidenartiges","tags":["Positiv","Nominativ","strong","Singular","neuter"]},{"form":"er ist pyramidenartig","tags":["Positiv","predicative","Singular","masculine"]},{"form":"es ist pyramidenartig","tags":["Positiv","predicative","Singular","neuter"]},{"form":"sie ist pyramidenartig","tags":["Positiv","predicative","Singular","feminine"]},{"form":"sie sind pyramidenartig","tags":["Positiv","predicative","Plural"]}],"senses":[{"definition":"an eine Pyramide erinnernd, wie eine Pyramide aussehend"}],"synonyms":[],"origins":[],"examples":[{"text":"„Es war eine riesige Krabbe, und anstelle eines Kopfes hatte es viele pyramidenartig angeordnete Ringe oder Knoten aus einer dicken, zähen Fleischmasse, bedeckt mit Fühlern.“","reference":"H.P. Lovecraft: Der Flüsterer im Dunkeln. In: Das Gesamtwerk: Sämtliche Erzählungen und Zusammenarbeiten. Festa, Leipzig 2020, ISBN 978-3-865-52882-7, Seite 1189 ."},{"text":"„Einmal schien es ihm für einen Moment, als nehme er weit entfernt mitten im Wald ein seltsames graues, pyramidenartiges Gebilde wahr, da verschwand es auch schon wieder.“","reference":"Ramsey Campbell: Die Mondlinse. In: Der Wahnsinn aus der Gruft. Festa, Leipzig 2014, ISBN 978-3-865-52314-3, Seite 54 ."}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"pyramidenartig","id":"b8476aa0ff41f0"},"0070-0079:8e1e8e7d84ef64":{"word":"Pyjamaoberteil","partOfSpeech":"Substantiv","gender":"das","hyphenation":{"de-CH":"Py·ja·ma·ober·teil","de-DE":"Py·ja·ma·ober·teil"},"forms":[{"form":"Pyjamaoberteil","tags":["Nominativ","Singular"]},{"form":"Pyjamaoberteile","tags":["Nominativ","Plural"]},{"form":"Pyjamaoberteils","tags":["Genitiv","Singular"]},{"form":"Pyjamaoberteilen","tags":["Dativ","Plural"]},{"form":"Pyjamaoberteiles","tags":["Genitiv","Singular"]}],"senses":[{"definition":"Oberteil eines Pyjamas"}],"synonyms":[],"origins":["Determinativkompositum aus den Substantiven Pyjama und Oberteil"],"examples":[{"text":"„Der Wachmann versuchte, ihn wegzuzerren; zwischen Pyjamaoberteil und Hose kam sein Bauch zum Vorschein, eine glatte Wölbung milchiger Haut.“","reference":"Clive Barker: Schweineblut-Blues. In: Die Bücher des Blutes I–III. Area Verlag, Erftstadt 2004, ISBN 3899960238, Seite 106"},{"text":"„Ich sah nach Alafair, ging dann in unser Schlafzimmer, wo Annie in Slip und Pyjamaoberteil auf dem Bauch schlief.“","reference":"James Lee Burke: Blut in den Bayous. Pendragon, Bielefeld 2016, ISBN 978-3-86532-563-1, Seite 105 ."}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Pyjamaoberteil","id":"8e1e8e7d84ef64"},"0070-0079:ae5bc0f35cbd4b":{"word":"Pygostyl","partOfSpeech":"Substantiv","gender":"das","hyphenation":{"de-CH":"Py·go·styl","de-DE":"Py·go·styl"},"forms":[{"form":"Pygostyl","tags":["Nominativ","Singular"]},{"form":"Pygostyle","tags":["Nominativ","Plural"]},{"form":"Pygostyls","tags":["Genitiv","Singular"]},{"form":"Pygostylen","tags":["Dativ","Plural"]}],"senses":[{"definition":"Skelettelement aus verwachsenen Schwanzwirbel am Skelett der Vögel, an denen die Schwanzfedern sitzen"}],"synonyms":[],"origins":["abgeleitet von Altgriechisch πυγή (pygē^☆) ^(→ grc) für „Rumpf“, „Schwanz“ und Altgriechisch στῦλος (stylos^☆) ^(→ grc) für „Säule“"],"examples":[{"text":"„Das Pygostyl dient als stabile Unterlage für die Schwanzfedern, die durch das Hochklappen des Pygostyls aufgestellt werden können.“","reference":"Patrick Messner, Frank Antwerpes: Pygostyl. In: flexikon.doccheck.com. 16. April 2019, abgerufen am 30. Juni 2024."},{"text":"„Die Pygostylia lassen sich in zwei Gruppen in Bezug auf das Pygostyl aufteilen. Das Pygostyl der Ornithothoraces hatte ein pflugscharförmiges Ende, während die primitiveren Arten eine eher längliches, stabförmiges Pygostyl besaßen.“","reference":"Familienliste Pygostylia. In: dinodata.de. Abgerufen am 30. Juni 2024."}],"idioms":[],"collocations":[],"derivations":["Pygostylia"],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Pygostyl","id":"ae5bc0f35cbd4b"},"0070-0079:0a219554cfeebd":{"word":"Pyramidenenergie","partOfSpeech":"Substantiv","gender":"die","hyphenation":{"de-CH":"Py·ra·mi·de·n·ener·gie","de-DE":"Py·ra·mi·de·n·ener·gie"},"forms":[{"form":"Pyramidenenergie","tags":["Nominativ","Singular"]}],"senses":[{"definition":"angeblicher Einfluss eines pyramidenförmigen Behälters oder Gebäudes auf darin befindliche Gegenstände und Lebewesen"}],"synonyms":[],"origins":["Determinativkompositum aus den Substantiven Pyramide und Energie mit dem Fugenelement -n"],"examples":[{"text":"„Genau wie sie an die harmonische Konvergenz der Planeten und an Pyramidenenergie geglaubt hatten, priesen Camille und Antonio diesen jungfräulichen Kontinent als ein Neues Atlantis an.“","reference":"Chuck Palahniuk: Verdammt. Manhattan, München 2014, ISBN 978-3-442-54745-6, Seite 274 ."}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Pyramidenenergie","id":"0a219554cfeebd"},"0070-0079:fa66b4cef74388":{"word":"Pyjamaparty","partOfSpeech":"Substantiv","gender":"die","hyphenation":{"de-CH":"Py·ja·ma·par·ty","de-DE":"Py·ja·ma·par·ty"},"forms":[{"form":"Pyjamaparty","tags":["Nominativ","Singular"]},{"form":"Pyjamapartys","tags":["Nominativ","Plural"]}],"senses":[{"definition":"Feier, auf der man Pyjamas trägt und in der Regel beim Gastgeber übernachtet"}],"synonyms":[],"origins":["Determinativkompositum aus den Substantiven Pyjama und Party"],"examples":[{"text":"„Nun postet die Sängerin ein Video von einer Pyjamaparty mit Kim und Khloé Kardashian.“","reference":"Britney Spears feiert Pyjamaparty mit Kardashian-Schwestern. In: Der Tagesspiegel Online. 2025-11-16 (URL, abgerufen am 4. Februar 2026) ."}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Pyjamaparty","id":"fa66b4cef74388"},"0070-0079:eaea2981b494a9":{"word":"Pyeongtaek","partOfSpeech":"Toponym","gender":"das","hyphenation":{"de-CH":"Pye·ongtaek","de-DE":"Pye·ongtaek"},"forms":[{"form":"Pyeongtaeks","tags":["Genitiv","Singular"]},{"form":"des Pyeongtaek","tags":["Genitiv","Singular"]},{"form":"des Pyeongtaeks","tags":["Genitiv","Singular"]},{"form":"(das) Pyeongtaek","tags":["Nominativ","Singular"]},{"form":"(dem) Pyeongtaek","tags":["Dativ","Singular"]}],"senses":[{"definition":"Großstadt in Südkorea"}],"synonyms":[],"origins":[],"examples":[{"text":"„Währenddessen waren Kolt und seine zahlenmäßig reduzierte Staffel zum Luftwaffenstützpunkt nahe Osan geflogen, direkt nördlich von Pyeongtaek.“","reference":"Dalton Fury: One Killer Force. Festa, Leipzig 2020, ISBN 978-3-86552-826-1, Seite 254 ."}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Pyeongtaek","id":"eaea2981b494a9"}};
